head.script:
/**/
(function(){
  try{
    var ua = navigator.userAgent || '';
    var isTouchMobile = /Android|iPhone|iPad|iPod|Mobile|SamsungBrowser|CriOS/i.test(ua);
    var url = new URL(window.location.href);
    var isForcedMobile = url.searchParams.get('m') === '1';
    var alreadyFixed = url.searchParams.get('brtv_mobile_fix') === '1';
    if ((isForcedMobile || (isTouchMobile && /(?:^|[?&])m=1(?:&|$)/.test(location.search))) && !alreadyFixed) {
      url.searchParams.set('m','0');
      url.searchParams.set('brtv_mobile_fix','1');
      url.searchParams.set('canal', url.searchParams.get('canal') || 'SBTSinop.br');
      url.searchParams.set('pais', url.searchParams.get('pais') || 'BR');
      url.searchParams.set('categoria', url.searchParams.get('categoria') || 'general');
      url.hash = 'watch';
      window.location.replace(url.toString());
    }
  }catch(e){}
})();
/**/

head.b:skin:
:root {
  --bbc-red: #bb1919;
  --bbc-red-dark: #8c0c0c;
  --bbc-red-bright: #d11b1b;
  --bbc-red-deep: #6e0a0a;
  --bbc-black: #000000;
  --bbc-near-black: #0a0a0a;
  --bbc-dark-grey: #141414;
  --bbc-medium-grey: #1d1d1d;
  --bbc-light-grey: #262626;
  --bbc-pale-grey: #383838;
  --bbc-mid: #4a4a4a;
  --bbc-white: #ffffff;
  --bbc-off-white: #f6f6f6;
  --bbc-cream: #f4f0e8;
  --text-primary: #ffffff;
  --text-secondary: #b8b8b8;
  --text-tertiary: #8a8a8a;
  --text-muted: #5a5a5a;
  --text-red: #ff3333;
  --live-red: #e60000;
  --live-glow: rgba(230, 0, 0, 0.5);
  --success: #00b04f;
  --warning: #ffa500;
  --info: #3b82f6;
  --accent-blue: #1e88e5;
  --border-thin: rgba(255, 255, 255, 0.06);
  --border-medium: rgba(255, 255, 255, 0.12);
  --border-bright: rgba(255, 255, 255, 0.22);
  --border-red: rgba(187, 25, 25, 0.4);
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.3);
  --shadow-md: 0 8px 24px rgba(0,0,0,0.4);
  --shadow-lg: 0 24px 60px rgba(0,0,0,0.6);
  --shadow-xl: 0 40px 100px rgba(0,0,0,0.7);
  --shadow-red: 0 8px 32px rgba(187, 25, 25, 0.4);
  --shadow-red-glow: 0 0 60px rgba(187, 25, 25, 0.25);
  --header-height: 76px;
  --topbar-height: 32px;
  --epg-height: 56px;
  --bottom-nav-height: 68px;
  --max-width: 1820px;
  --player-width: 100%;
  --channel-list-width: 380px;
  --font-display: 'Fraunces', 'Georgia', serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'IBM Plex Mono', 'Courier New', monospace;
  --font-condensed: 'Bebas Neue', 'Arial Narrow', sans-serif;
}

* { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html { scroll-behavior: smooth; }

html, body {
  background: var(--bbc-black);
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 15px;
  line-height: 1.55;
  font-weight: 400;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  letter-spacing: -0.005em;
  font-feature-settings: 'kern' 1, 'liga' 1, 'calt' 1;
}

body {
  background:
    radial-gradient(ellipse 100% 80% at 50% 0%, rgba(187, 25, 25, 0.06) 0%, transparent 50%),
    radial-gradient(ellipse 60% 60% at 90% 50%, rgba(187, 25, 25, 0.03) 0%, transparent 50%),
    var(--bbc-black);
  min-height: 100vh;
  min-height: 100dvh;
  padding-bottom: env(safe-area-inset-bottom);
}

@media all and (display-mode: standalone) {
  body { padding-top: env(safe-area-inset-top); }
  .install-banner, .install-modal-backdrop, .header-install-btn { display: none !important; }
  .pwa-installed-badge { display: inline-flex !important; }
}

@media all and (display-mode: minimal-ui) {
  .install-banner, .install-modal-backdrop { display: none !important; }
}

a { color: inherit; text-decoration: none; transition: color 0.2s ease; }
img { max-width: 100%; display: block; }
button { font-family: inherit; cursor: pointer; border: none; outline: none; background: none; color: inherit; }
input { font-family: inherit; }

::selection { background: var(--bbc-red); color: white; }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: var(--bbc-near-black); }
::-webkit-scrollbar-thumb { background: var(--bbc-pale-grey); border-radius: 5px; border: 2px solid var(--bbc-near-black); }
::-webkit-scrollbar-thumb:hover { background: var(--bbc-red); }

.splash-screen {
  position: fixed;
  inset: 0;
  z-index: 9999;
  background: var(--bbc-black);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 36px;
  transition: opacity 0.6s ease, visibility 0.6s ease;
}

.splash-screen.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.splash-bg-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px);
  background-size: 60px 60px;
  mask: radial-gradient(ellipse at center, black 30%, transparent 70%);
  -webkit-mask: radial-gradient(ellipse at center, black 30%, transparent 70%);
}

.splash-logo {
  display: flex;
  align-items: center;
  gap: 14px;
  position: relative;
  animation: splashFadeIn 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.splash-bar {
  width: 8px;
  height: 60px;
  background: var(--bbc-red);
  animation: splashBarGrow 0.7s cubic-bezier(0.16, 1, 0.3, 1) 0.2s backwards;
  box-shadow: 0 0 30px var(--bbc-red);
}

.splash-text {
  font-family: var(--font-sans);
  font-weight: 900;
  font-size: 60px;
  letter-spacing: -3px;
  line-height: 1;
  display: flex;
  gap: 6px;
}

.splash-text span {
  opacity: 0;
  animation: splashTextIn 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.splash-text span:nth-child(1) { animation-delay: 0.3s; }
.splash-text span:nth-child(2) { animation-delay: 0.45s; }
.splash-text span:nth-child(3) { animation-delay: 0.6s; color: var(--bbc-red); }

.splash-loader {
  width: 320px;
  height: 2px;
  background: var(--bbc-medium-grey);
  position: relative;
  overflow: hidden;
}

.splash-loader::after {
  content: '';
  position: absolute;
  inset: 0;
  background: var(--bbc-red);
  transform: translateX(-100%);
  animation: splashLoad 1.6s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

.splash-status {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 4px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  animation: splashFadeIn 0.6s ease 0.8s backwards;
  display: flex;
  align-items: center;
  gap: 12px;
}

.splash-status::before, .splash-status::after {
  content: '';
  width: 24px;
  height: 1px;
  background: var(--text-muted);
}

.splash-version {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 3px;
  color: var(--text-muted);
  position: absolute;
  bottom: 40px;
  text-transform: uppercase;
}

@keyframes splashFadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
@keyframes splashBarGrow { from { height: 0; } to { height: 60px; } }
@keyframes splashTextIn { from { opacity: 0; transform: translateY(20px); filter: blur(8px); } to { opacity: 1; transform: translateY(0); filter: blur(0); } }
@keyframes splashLoad { 0% { transform: translateX(-100%); } 100% { transform: translateX(0%); } }

.install-banner {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 9000;
  background: linear-gradient(90deg, var(--bbc-red) 0%, var(--bbc-red-bright) 50%, var(--bbc-red) 100%);
  color: white;
  display: none;
  align-items: center;
  gap: 14px;
  padding: 10px 16px;
  padding-top: calc(10px + env(safe-area-inset-top));
  box-shadow: 0 4px 24px rgba(187,25,25,0.5);
  animation: slideDownBanner 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

.install-banner.visible { display: flex; }

@keyframes slideDownBanner {
  from { transform: translateY(-100%); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

.install-banner-icon {
  width: 40px;
  height: 40px;
  background: rgba(255,255,255,0.18);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border: 1.5px solid rgba(255,255,255,0.3);
  position: relative;
  font-weight: 900;
  font-size: 14px;
  letter-spacing: -0.5px;
}

.install-banner-icon::after {
  content: '';
  position: absolute;
  top: -3px;
  right: -3px;
  width: 10px;
  height: 10px;
  background: var(--success);
  border-radius: 50%;
  border: 2px solid var(--bbc-red);
  animation: live-pulse 1.5s ease-in-out infinite;
}

.install-banner-text {
  flex: 1;
  min-width: 0;
}

.install-banner-title {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: -0.2px;
  line-height: 1.2;
  margin-bottom: 2px;
}

.install-banner-sub {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.8px;
  opacity: 0.95;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.install-banner-btn {
  background: white;
  color: var(--bbc-red);
  padding: 9px 16px;
  border-radius: 4px;
  font-weight: 800;
  font-size: 12px;
  letter-spacing: 0.3px;
  cursor: pointer;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: transform 0.2s ease;
  text-transform: uppercase;
}

.install-banner-btn:hover { transform: scale(1.05); }
.install-banner-btn:active { transform: scale(0.96); }
.install-banner-btn svg { width: 13px; height: 13px; }

.install-banner-close {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border-radius: 50%;
  background: rgba(0,0,0,0.15);
  flex-shrink: 0;
  transition: background 0.2s ease;
}

.install-banner-close:hover { background: rgba(0,0,0,0.3); }
.install-banner-close svg { width: 14px; height: 14px; }

body.install-banner-visible { padding-top: 64px; }

@media (max-width: 768px) {
  .install-banner { padding: 8px 12px; padding-top: calc(8px + env(safe-area-inset-top)); gap: 10px; }
  .install-banner-icon { width: 36px; height: 36px; font-size: 12px; }
  .install-banner-title { font-size: 12px; }
  .install-banner-sub { font-size: 9px; letter-spacing: 0.4px; }
  .install-banner-btn { padding: 8px 12px; font-size: 11px; }
  .install-banner-close { width: 28px; height: 28px; }
  body.install-banner-visible { padding-top: 58px; }
}

.install-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.85);
  backdrop-filter: blur(12px);
  z-index: 9500;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: modalFadeIn 0.3s ease;
}

.install-modal-backdrop.visible { display: flex; }

@keyframes modalFadeIn { from { opacity: 0; } to { opacity: 1; } }

.install-modal {
  background: var(--bbc-dark-grey);
  border: 1px solid var(--border-medium);
  border-radius: 8px;
  max-width: 440px;
  width: 100%;
  max-height: 90vh;
  overflow-y: auto;
  animation: modalSlideIn 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  box-shadow: var(--shadow-xl);
  position: relative;
}

@keyframes modalSlideIn {
  from { opacity: 0; transform: translateY(40px) scale(0.95); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.install-modal-header {
  padding: 24px 24px 0;
  text-align: center;
  position: relative;
}

.install-modal-close {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  cursor: pointer;
  background: var(--bbc-medium-grey);
  transition: background 0.2s ease;
}

.install-modal-close:hover { background: var(--bbc-light-grey); }
.install-modal-close svg { width: 14px; height: 14px; }

.install-modal-icon {
  width: 88px;
  height: 88px;
  background: var(--bbc-red);
  border-radius: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  margin: 0 auto 18px;
  font-weight: 900;
  color: white;
  box-shadow: 0 10px 40px var(--shadow-red);
  position: relative;
}

.install-modal-icon-main {
  font-size: 28px;
  letter-spacing: -1px;
  line-height: 1;
}

.install-modal-icon-sub {
  font-size: 11px;
  letter-spacing: 1px;
  margin-top: 4px;
  opacity: 0.95;
}

.install-modal-icon::after {
  content: '';
  position: absolute;
  bottom: -4px;
  right: -4px;
  width: 22px;
  height: 22px;
  background: var(--success);
  border-radius: 50%;
  border: 3px solid var(--bbc-dark-grey);
}

.install-modal-title {
  font-family: var(--font-display);
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.8px;
  color: var(--text-primary);
  margin-bottom: 6px;
  line-height: 1.1;
}

.install-modal-title em {
  font-style: italic;
  color: var(--bbc-red);
  font-weight: 400;
}

.install-modal-sub {
  font-size: 13px;
  color: var(--text-secondary);
  margin-bottom: 22px;
  line-height: 1.5;
}

.install-modal-body { padding: 0 24px 24px; }

.install-features {
  background: var(--bbc-near-black);
  border-radius: 6px;
  padding: 14px;
  margin-bottom: 20px;
}

.install-feature {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 0;
  font-size: 13px;
  color: var(--text-secondary);
}

.install-feature-icon {
  width: 26px;
  height: 26px;
  background: rgba(187,25,25,0.15);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.install-feature-icon svg { width: 13px; height: 13px; color: var(--bbc-red); }

.install-feature-text {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-primary);
  letter-spacing: -0.1px;
}

.install-feature-text span {
  display: block;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 400;
  color: var(--text-tertiary);
  letter-spacing: 0.5px;
  margin-top: 1px;
}

.install-modal-cta {
  width: 100%;
  background: var(--bbc-red);
  color: white;
  padding: 14px 20px;
  border-radius: 6px;
  font-weight: 800;
  font-size: 14px;
  letter-spacing: 0.5px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: all 0.2s ease;
  text-transform: uppercase;
  box-shadow: 0 8px 24px var(--shadow-red);
}

.install-modal-cta:hover { background: var(--bbc-red-bright); transform: translateY(-2px); }
.install-modal-cta:active { transform: scale(0.98); }
.install-modal-cta svg { width: 16px; height: 16px; }

.install-modal-secondary {
  width: 100%;
  background: transparent;
  color: var(--text-tertiary);
  padding: 12px;
  font-weight: 600;
  font-size: 11px;
  letter-spacing: 1.5px;
  cursor: pointer;
  text-transform: uppercase;
  margin-top: 8px;
  transition: color 0.2s ease;
}

.install-modal-secondary:hover { color: var(--text-primary); }

.install-instructions {
  background: var(--bbc-near-black);
  border-radius: 6px;
  padding: 16px;
  margin-top: 14px;
  border-left: 3px solid var(--bbc-red);
}

.install-instructions-title {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--bbc-red);
  text-transform: uppercase;
  margin-bottom: 12px;
}

.install-step {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 10px;
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.5;
}

.install-step:last-child { margin-bottom: 0; }

.install-step-num {
  width: 22px;
  height: 22px;
  background: var(--bbc-red);
  color: white;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 11px;
  flex-shrink: 0;
}

.install-step-text strong { color: var(--text-primary); font-weight: 700; }

.pwa-installed-badge {
  display: none;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  background: rgba(0,176,79,0.12);
  border: 1px solid var(--success);
  color: var(--success);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
  border-radius: 3px;
  text-transform: uppercase;
}

.pwa-installed-badge::before {
  content: '';
  width: 6px;
  height: 6px;
  background: var(--success);
  border-radius: 50%;
}

.top-bar {
  background: var(--bbc-black);
  border-bottom: 1px solid var(--border-thin);
  padding: 7px 0;
  font-size: 11px;
  font-weight: 500;
  position: relative;
  z-index: 99;
}

.top-bar-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.top-bar-left, .top-bar-right {
  display: flex;
  align-items: center;
  gap: 18px;
  color: var(--text-tertiary);
}

.top-bar-item {
  display: flex;
  align-items: center;
  gap: 7px;
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.5px;
}

.top-bar-item.live-indicator { color: var(--text-red); font-weight: 700; }

.top-bar-item .dot {
  width: 7px;
  height: 7px;
  background: var(--live-red);
  border-radius: 50%;
  animation: live-pulse 1.2s ease-in-out infinite;
}

@keyframes live-pulse {
  0%, 100% { opacity: 1; transform: scale(1); box-shadow: 0 0 0 0 var(--live-glow); }
  50% { opacity: 0.6; transform: scale(0.85); box-shadow: 0 0 0 6px transparent; }
}

.top-bar-clock {
  font-family: var(--font-mono);
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: 1px;
  font-size: 12px;
}

.top-bar-divider { width: 1px; height: 12px; background: var(--border-medium); }
.top-bar-stock { display: flex; align-items: center; gap: 6px; }
.top-bar-stock-name { color: var(--text-tertiary); font-size: 10px; letter-spacing: 1px; }
.top-bar-stock-value { color: var(--text-primary); font-weight: 700; }
.top-bar-stock-change { font-size: 10px; font-weight: 600; padding: 1px 5px; border-radius: 2px; }
.top-bar-stock-change.up { color: var(--success); background: rgba(0,176,79,0.1); }
.top-bar-stock-change.down { color: var(--bbc-red-bright); background: rgba(187,25,25,0.15); }

.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(0, 0, 0, 0.94);
  backdrop-filter: blur(24px) saturate(180%);
  -webkit-backdrop-filter: blur(24px) saturate(180%);
  border-bottom: 4px solid var(--bbc-red);
  box-shadow: 0 4px 24px rgba(0,0,0,0.5);
  transition: top 0.3s ease;
}

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 14px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
}

.logo {
  display: flex;
  align-items: stretch;
  gap: 0;
  position: relative;
  text-decoration: none;
  flex-shrink: 0;
}

.logo-blocks { display: flex; gap: 3px; }

.logo-block {
  background: var(--bbc-white);
  color: var(--bbc-black);
  padding: 10px 12px;
  font-family: var(--font-sans);
  font-weight: 900;
  font-size: 22px;
  letter-spacing: -1.5px;
  line-height: 1;
  display: flex;
  align-items: center;
  position: relative;
  transition: all 0.3s ease;
}

.logo-block.accent {
  background: var(--bbc-red);
  color: var(--bbc-white);
  position: relative;
}

.logo-block.accent::after {
  content: '';
  position: absolute;
  right: -3px;
  top: 0;
  bottom: 0;
  width: 3px;
  background: var(--bbc-red);
}

.logo:hover .logo-block { transform: translateY(-1px); }
.logo:hover .logo-block.accent { box-shadow: 0 4px 20px var(--shadow-red); }

.logo-meta {
  display: flex;
  flex-direction: column;
  justify-content: center;
  margin-left: 16px;
  padding-left: 16px;
  border-left: 1px solid var(--border-medium);
}

.logo-meta-title {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 15px;
  color: var(--text-primary);
  line-height: 1;
  letter-spacing: -0.3px;
  font-style: italic;
}

.logo-meta-sub {
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 3px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  margin-top: 5px;
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 2px;
  flex: 1;
  justify-content: center;
}

.nav-item {
  padding: 10px 18px;
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 600;
  color: var(--text-secondary);
  border-radius: 3px;
  transition: all 0.2s ease;
  cursor: pointer;
  position: relative;
  letter-spacing: -0.2px;
}

.nav-item:hover { color: var(--text-primary); background: var(--bbc-medium-grey); }
.nav-item.active { color: var(--text-primary); }

.nav-item.active::after {
  content: '';
  position: absolute;
  bottom: -18px;
  left: 50%;
  transform: translateX(-50%);
  width: 30px;
  height: 3px;
  background: var(--bbc-red);
}

.nav-item .nav-badge {
  background: var(--bbc-red);
  color: white;
  font-size: 9px;
  font-weight: 700;
  padding: 1px 5px;
  border-radius: 10px;
  margin-left: 6px;
  vertical-align: middle;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.header-install-btn {
  display: none;
  align-items: center;
  gap: 7px;
  padding: 9px 14px;
  background: var(--bbc-red);
  color: white;
  border-radius: 3px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.3px;
  cursor: pointer;
  transition: all 0.2s ease;
  text-transform: uppercase;
  box-shadow: 0 2px 12px var(--shadow-red);
  position: relative;
}

.header-install-btn.visible { display: inline-flex; }
.header-install-btn:hover { background: var(--bbc-red-bright); transform: translateY(-1px); }
.header-install-btn svg { width: 13px; height: 13px; }

.header-install-btn::after {
  content: '';
  position: absolute;
  top: -3px;
  right: -3px;
  width: 8px;
  height: 8px;
  background: var(--success);
  border-radius: 50%;
  border: 2px solid var(--bbc-black);
  animation: live-pulse 1.5s ease-in-out infinite;
}

.search-box { position: relative; width: 320px; }

.search-input {
  width: 100%;
  background: var(--bbc-medium-grey);
  border: 1px solid transparent;
  color: var(--text-primary);
  padding: 10px 16px 10px 38px;
  border-radius: 3px;
  font-size: 13px;
  font-weight: 500;
  transition: all 0.2s ease;
}

.search-input::placeholder { color: var(--text-muted); font-weight: 400; }

.search-input:focus {
  border-color: var(--bbc-red);
  background: var(--bbc-dark-grey);
  outline: none;
  box-shadow: 0 0 0 3px rgba(187,25,25,0.1);
}

.search-box::before {
  content: '';
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  width: 14px;
  height: 14px;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23999' stroke-width='2.5' stroke-linecap='round'><circle cx='11' cy='11' r='8'/><line x1='21' y1='21' x2='16.65' y2='16.65'/></svg>");
  background-size: contain;
  background-repeat: no-repeat;
  pointer-events: none;
  z-index: 2;
}

.search-results {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  right: 0;
  background: var(--bbc-dark-grey);
  border: 1px solid var(--border-medium);
  border-radius: 3px;
  max-height: 420px;
  overflow-y: auto;
  z-index: 200;
  display: none;
  box-shadow: var(--shadow-xl);
}

.search-results.visible { display: block; }

.search-results-header {
  padding: 10px 14px;
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 2px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  border-bottom: 1px solid var(--border-thin);
  background: var(--bbc-near-black);
}

.search-result-item {
  padding: 12px 14px;
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  border-bottom: 1px solid var(--border-thin);
  transition: background 0.15s ease;
}

.search-result-item:hover { background: var(--bbc-medium-grey); }
.search-result-item:last-child { border-bottom: none; }

.search-result-thumb {
  width: 44px;
  height: 44px;
  border-radius: 3px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 13px;
  color: white;
  flex-shrink: 0;
}

.search-result-meta { flex: 1; min-width: 0; }

.search-result-name {
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.search-result-cat {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-top: 2px;
}

.country-selector { position: relative; }

.country-btn {
  background: var(--bbc-medium-grey);
  color: var(--text-primary);
  padding: 10px 14px;
  border-radius: 3px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  font-weight: 600;
  transition: all 0.2s ease;
  border: 1px solid transparent;
}

.country-btn:hover { background: var(--bbc-light-grey); border-color: var(--bbc-red); }
.country-flag { font-size: 18px; line-height: 1; }
.country-btn svg { opacity: 0.6; transition: transform 0.2s ease; }
.country-btn.open svg { transform: rotate(180deg); }

.country-dropdown {
  position: absolute;
  right: 0;
  top: calc(100% + 8px);
  background: var(--bbc-dark-grey);
  border: 1px solid var(--border-medium);
  border-radius: 3px;
  padding: 6px;
  min-width: 260px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all 0.2s ease;
  box-shadow: var(--shadow-xl);
  max-height: 480px;
  overflow-y: auto;
  z-index: 200;
}

.country-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }

.country-option {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border-radius: 3px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all 0.15s ease;
  position: relative;
}

.country-option:hover { background: var(--bbc-medium-grey); color: var(--text-primary); }

.country-option.active {
  background: rgba(187, 25, 25, 0.15);
  color: var(--text-primary);
  font-weight: 600;
}

.country-option.active::before {
  content: '';
  position: absolute;
  left: 0;
  top: 6px;
  bottom: 6px;
  width: 3px;
  background: var(--bbc-red);
}

.country-count {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-muted);
  background: var(--bbc-medium-grey);
  padding: 2px 8px;
  border-radius: 10px;
}

.country-option.active .country-count { background: var(--bbc-red); color: white; }

.epg-bar {
  background: var(--bbc-near-black);
  border-bottom: 1px solid var(--border-thin);
  padding: 11px 0;
  overflow-x: auto;
  scrollbar-width: none;
  position: sticky;
  top: calc(var(--header-height) + 4px);
  z-index: 90;
}

.epg-bar::-webkit-scrollbar { display: none; }

.epg-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  gap: 18px;
}

.epg-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--bbc-red);
  text-transform: uppercase;
  flex-shrink: 0;
  padding-right: 18px;
  border-right: 1px solid var(--border-medium);
}

.epg-items { display: flex; gap: 28px; flex: 1; white-space: nowrap; }

.epg-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  cursor: pointer;
  padding: 4px 0;
  transition: opacity 0.2s ease;
}

.epg-item:hover { opacity: 0.7; }

.epg-time {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 1px;
  color: var(--text-tertiary);
  text-transform: uppercase;
}

.epg-time.now { color: var(--bbc-red); }

.epg-program {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: -0.2px;
}

.epg-channel { font-size: 11px; color: var(--text-secondary); font-weight: 500; }

/* PLACEHOLDER - será removido na concatenação */
.priority-layout-container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 20px 24px 0;
}

.live-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 14px;
  padding: 10px 16px;
  background: linear-gradient(90deg, rgba(187, 25, 25, 0.15) 0%, transparent 100%);
  border-left: 3px solid var(--bbc-red);
}

.live-banner-left {
  display: flex;
  align-items: center;
  gap: 14px;
  flex: 1;
  min-width: 0;
}

.live-banner-tag {
  background: var(--bbc-red);
  color: white;
  padding: 5px 11px;
  font-family: var(--font-sans);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 2px;
  text-transform: uppercase;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 2px;
  flex-shrink: 0;
}

.live-banner-tag::before {
  content: '';
  width: 7px;
  height: 7px;
  background: white;
  border-radius: 50%;
  animation: live-pulse 1.2s ease-in-out infinite;
}

.live-banner-text {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 16px;
  font-weight: 500;
  letter-spacing: -0.3px;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}

.live-banner-text strong {
  font-weight: 700;
  font-style: normal;
  color: var(--bbc-red);
}

.live-banner-right {
  display: flex;
  align-items: center;
  gap: 14px;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 1.5px;
  flex-shrink: 0;
}

.live-banner-viewers {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-primary);
  font-weight: 700;
}

.live-banner-viewers::before {
  content: '';
  width: 6px;
  height: 6px;
  background: var(--live-red);
  border-radius: 50%;
  animation: live-pulse 1.5s ease-in-out infinite;
}

.priority-section {
  display: grid;
  grid-template-columns: 1fr var(--channel-list-width);
  gap: 20px;
  margin-bottom: 40px;
}

.player-master {
  display: flex;
  flex-direction: column;
  gap: 0;
  background: var(--bbc-near-black);
  border: 1px solid var(--border-thin);
  overflow: hidden;
  box-shadow: var(--shadow-xl), var(--shadow-red-glow);
  position: relative;
}

.player-master::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--bbc-red) 0%, var(--bbc-red-bright) 50%, var(--bbc-red) 100%);
  z-index: 5;
}

.player-frame {
  position: relative;
  width: 100%;
  padding-bottom: 56.25%;
  background: #000;
}

.player-frame iframe,
.player-frame .player-placeholder {
  position: absolute;
  top: 0; left: 0;
  width: 100%;
  height: 100%;
  border: 0;
}

.player-placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 20px;
  background:
    radial-gradient(ellipse at center, rgba(187, 25, 25, 0.1) 0%, transparent 70%),
    linear-gradient(135deg, var(--bbc-black) 0%, var(--bbc-near-black) 100%);
  color: var(--text-tertiary);
  text-align: center;
  padding: 40px;
}

.player-placeholder-icon {
  font-size: 80px;
  opacity: 0.3;
  font-family: var(--font-display);
}

.player-placeholder-text {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 24px;
  font-weight: 400;
  color: var(--text-secondary);
  letter-spacing: -0.5px;
}

.player-placeholder-sub {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 3px;
  color: var(--text-muted);
  text-transform: uppercase;
}

.player-signal {
  position: absolute;
  top: 16px;
  right: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(0,0,0,0.75);
  backdrop-filter: blur(8px);
  padding: 7px 12px;
  border-radius: 2px;
  z-index: 10;
  pointer-events: none;
}

.signal-bars {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 14px;
}

.signal-bar {
  width: 3px;
  background: var(--success);
  animation: signal-pulse 2s ease-in-out infinite;
}

.signal-bar:nth-child(1) { height: 30%; animation-delay: 0s; }
.signal-bar:nth-child(2) { height: 55%; animation-delay: 0.2s; }
.signal-bar:nth-child(3) { height: 75%; animation-delay: 0.4s; }
.signal-bar:nth-child(4) { height: 100%; animation-delay: 0.6s; }

@keyframes signal-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.signal-text {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: white;
}

.player-watermark {
  position: absolute;
  top: 16px;
  left: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
  z-index: 10;
  pointer-events: none;
}

.player-watermark-logo {
  background: var(--bbc-red);
  color: white;
  padding: 4px 8px;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: -0.5px;
  border-radius: 2px;
  display: flex;
  align-items: center;
  gap: 4px;
}

.player-watermark-logo::before {
  content: '';
  width: 5px;
  height: 5px;
  background: white;
  border-radius: 50%;
  animation: live-pulse 1.2s ease-in-out infinite;
}

.player-controls {
  background: var(--bbc-near-black);
  padding: 14px 22px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-top: 1px solid var(--border-thin);
  flex-wrap: wrap;
}

.player-ctrl-btn {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--bbc-medium-grey);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;
  position: relative;
}

.player-ctrl-btn:hover {
  background: var(--bbc-red);
  transform: scale(1.05);
}

.player-ctrl-btn:hover::after {
  content: attr(title);
  position: absolute;
  bottom: -32px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--bbc-black);
  color: white;
  padding: 4px 8px;
  border-radius: 2px;
  font-size: 10px;
  font-family: var(--font-mono);
  letter-spacing: 1px;
  white-space: nowrap;
  z-index: 100;
  border: 1px solid var(--border-medium);
}

.player-ctrl-btn svg { width: 17px; height: 17px; }

.player-ctrl-btn.primary {
  width: 48px;
  height: 48px;
  background: var(--bbc-red);
  box-shadow: 0 4px 16px var(--shadow-red);
}

.player-ctrl-btn.primary:hover { background: var(--bbc-red-bright); }
.player-ctrl-btn.primary svg { width: 22px; height: 22px; }

.player-time-block {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 1.5px;
  color: var(--text-tertiary);
  margin-left: 6px;
}

.player-time-block .rec-dot {
  width: 9px;
  height: 9px;
  background: var(--live-red);
  border-radius: 50%;
  animation: live-pulse 1.2s ease-in-out infinite;
  box-shadow: 0 0 10px var(--live-glow);
}

.player-time-block .time-val {
  color: var(--text-primary);
  font-weight: 700;
  font-size: 12px;
}

.player-ctrl-spacer { flex: 1; min-width: 20px; }

.player-volume {
  display: flex;
  align-items: center;
  gap: 8px;
}

.volume-slider {
  width: 80px;
  height: 4px;
  background: var(--bbc-medium-grey);
  border-radius: 2px;
  position: relative;
  cursor: pointer;
}

.volume-fill {
  position: absolute;
  inset: 0;
  width: 70%;
  background: var(--bbc-red);
  border-radius: 2px;
}

.volume-handle {
  position: absolute;
  top: 50%;
  left: 70%;
  transform: translate(-50%, -50%);
  width: 12px;
  height: 12px;
  background: white;
  border-radius: 50%;
  cursor: pointer;
}

.player-info-bar {
  background: var(--bbc-dark-grey);
  padding: 18px 22px;
  border-top: 4px solid var(--bbc-red);
}

.player-info-meta-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 2px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  flex-wrap: wrap;
}

.player-meta-tag {
  background: var(--bbc-medium-grey);
  padding: 4px 10px;
  border-radius: 2px;
  font-weight: 600;
  color: var(--text-primary);
}

.player-meta-tag.red {
  background: var(--bbc-red);
  color: white;
}

.player-meta-tag.outlined {
  background: transparent;
  border: 1px solid var(--border-medium);
  color: var(--text-secondary);
}

.player-meta-divider {
  width: 3px;
  height: 3px;
  background: var(--text-muted);
  border-radius: 50%;
}

.player-channel-title {
  font-family: var(--font-display);
  font-size: 36px;
  font-weight: 700;
  letter-spacing: -1.2px;
  margin-bottom: 8px;
  line-height: 1;
  color: var(--text-primary);
}

.player-channel-desc {
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1.6;
  max-width: 800px;
  font-weight: 400;
}

.player-action-row {
  display: flex;
  gap: 8px;
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid var(--border-thin);
  flex-wrap: wrap;
  align-items: center;
}

.player-action {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 9px 14px;
  background: var(--bbc-medium-grey);
  border-radius: 3px;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.player-action:hover { background: var(--bbc-light-grey); }
.player-action.active { background: var(--bbc-red); color: white; }
.player-action svg { width: 13px; height: 13px; }

.channel-list-side {
  background: var(--bbc-dark-grey);
  border: 1px solid var(--border-thin);
  display: flex;
  flex-direction: column;
  max-height: calc(100vh - 200px);
  min-height: 500px;
  overflow: hidden;
  position: sticky;
  top: 130px;
}

.channel-list-header {
  background: var(--bbc-near-black);
  border-bottom: 3px solid var(--bbc-red);
  padding: 16px 18px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.channel-list-title {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 700;
  letter-spacing: -0.5px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.channel-list-title em {
  font-style: italic;
  font-weight: 400;
  color: var(--bbc-red);
}

.channel-list-badge {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  color: var(--bbc-red);
  background: rgba(187,25,25,0.12);
  padding: 4px 9px;
  border-radius: 2px;
  letter-spacing: 1.5px;
  display: flex;
  align-items: center;
  gap: 5px;
}

.channel-list-badge::before {
  content: '';
  width: 5px;
  height: 5px;
  background: var(--bbc-red);
  border-radius: 50%;
  animation: live-pulse 1.3s ease-in-out infinite;
}

.channel-list-tabs {
  display: flex;
  background: var(--bbc-near-black);
  border-bottom: 1px solid var(--border-thin);
  overflow-x: auto;
  scrollbar-width: none;
}

.channel-list-tabs::-webkit-scrollbar { display: none; }

.list-tab {
  padding: 11px 14px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: var(--text-tertiary);
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s ease;
  position: relative;
  flex-shrink: 0;
}

.list-tab:hover { color: var(--text-primary); }

.list-tab.active { color: var(--text-primary); }

.list-tab.active::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 14px;
  right: 14px;
  height: 3px;
  background: var(--bbc-red);
}

.channel-list-search {
  padding: 10px 14px;
  border-bottom: 1px solid var(--border-thin);
  position: relative;
}

.channel-list-search input {
  width: 100%;
  background: var(--bbc-medium-grey);
  border: 1px solid transparent;
  color: var(--text-primary);
  padding: 8px 12px 8px 32px;
  border-radius: 2px;
  font-size: 12px;
  font-weight: 500;
}

.channel-list-search input:focus {
  outline: none;
  border-color: var(--bbc-red);
}

.channel-list-search::before {
  content: '';
  position: absolute;
  left: 22px;
  top: 50%;
  transform: translateY(-50%);
  width: 12px;
  height: 12px;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23999' stroke-width='2.5' stroke-linecap='round'><circle cx='11' cy='11' r='8'/><line x1='21' y1='21' x2='16.65' y2='16.65'/></svg>");
  background-size: contain;
  background-repeat: no-repeat;
  pointer-events: none;
}

.channel-list-categories {
  display: flex;
  gap: 6px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border-thin);
  overflow-x: auto;
  scrollbar-width: none;
}

.channel-list-categories::-webkit-scrollbar { display: none; }

.list-cat-pill {
  background: var(--bbc-medium-grey);
  color: var(--text-secondary);
  padding: 6px 12px;
  border-radius: 100px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.5px;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.2s ease;
  text-transform: uppercase;
}

.list-cat-pill:hover { background: var(--bbc-light-grey); color: var(--text-primary); }

.list-cat-pill.active {
  background: var(--bbc-red);
  color: white;
}

.channel-list-body {
  flex: 1;
  overflow-y: auto;
  padding: 6px;
}

.channel-list-group {
  margin-bottom: 8px;
}

.list-group-header {
  padding: 10px 12px 6px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
}

.list-group-title {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2.5px;
  color: var(--bbc-red);
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: 8px;
}

.list-group-title::before {
  content: '';
  width: 3px;
  height: 11px;
  background: var(--bbc-red);
}

.list-group-count {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-tertiary);
  background: var(--bbc-medium-grey);
  padding: 2px 7px;
  border-radius: 2px;
}

.list-channel-item {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px 12px;
  border-radius: 3px;
  cursor: pointer;
  transition: all 0.18s ease;
  position: relative;
  margin-bottom: 2px;
}

.list-channel-item:hover { background: var(--bbc-medium-grey); }

.list-channel-item.active {
  background: var(--bbc-medium-grey);
}

.list-channel-item.active::before {
  content: '';
  position: absolute;
  left: 0;
  top: 10px;
  bottom: 10px;
  width: 3px;
  background: var(--bbc-red);
}

.list-channel-thumb {
  width: 48px;
  height: 48px;
  border-radius: 3px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  font-weight: 900;
  font-size: 13px;
  letter-spacing: -0.3px;
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
  color: white;
}

.list-channel-thumb::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(255,255,255,0.12) 0%, transparent 50%);
}

.list-channel-thumb-live {
  position: absolute;
  bottom: 2px;
  right: 2px;
  background: var(--bbc-red);
  color: white;
  font-size: 7px;
  font-weight: 800;
  padding: 1px 4px;
  letter-spacing: 0.5px;
  border-radius: 1px;
  z-index: 2;
  line-height: 1;
}

.list-channel-meta { flex: 1; min-width: 0; }

.list-channel-name {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: -0.2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--text-primary);
  margin-bottom: 3px;
}

.list-channel-info {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.list-channel-viewers {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--bbc-red);
  font-weight: 700;
}

.list-channel-viewers::before {
  content: '';
  width: 5px;
  height: 5px;
  background: var(--live-red);
  border-radius: 50%;
  animation: live-pulse 1.5s ease-in-out infinite;
}

.list-channel-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.list-channel-fav {
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 3px;
  cursor: pointer;
  transition: background 0.15s ease;
  background: transparent;
}

.list-channel-fav:hover { background: var(--bbc-light-grey); }

.list-channel-fav svg {
  width: 13px;
  height: 13px;
  fill: none;
  stroke: var(--text-tertiary);
  stroke-width: 2;
  transition: all 0.2s ease;
}

.list-channel-fav.active svg {
  fill: var(--bbc-red);
  stroke: var(--bbc-red);
}

.list-channel-position {
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--text-muted);
  font-weight: 600;
}

.channel-list-footer {
  padding: 12px 14px;
  background: var(--bbc-near-black);
  border-top: 1px solid var(--border-thin);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-tertiary);
  letter-spacing: 1px;
  text-transform: uppercase;
}

.channel-list-footer .stats {
  display: flex;
  align-items: center;
  gap: 12px;
}

.channel-list-footer .stat-pill {
  display: flex;
  align-items: center;
  gap: 4px;
}

.channel-list-footer .stat-pill .val {
  color: var(--text-primary);
  font-weight: 700;
}

.list-empty {
  padding: 60px 20px;
  text-align: center;
  color: var(--text-tertiary);
}

.list-empty-icon {
  font-size: 48px;
  opacity: 0.3;
  font-family: var(--font-display);
  margin-bottom: 12px;
}

.list-empty-text {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 16px;
  color: var(--text-secondary);
}

.editorial-section {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 30px 24px;
}

.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 40px;
  margin-bottom: 50px;
}

.editorial-main {
  position: relative;
}

.editorial-tag {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 6px 12px;
  background: var(--bbc-red);
  color: white;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  margin-bottom: 20px;
}

.editorial-tag::before {
  content: '';
  width: 6px;
  height: 6px;
  background: white;
  border-radius: 50%;
  animation: live-pulse 1.2s ease-in-out infinite;
}

.editorial-headline {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(36px, 6vw, 72px);
  line-height: 0.95;
  letter-spacing: -2.5px;
  color: var(--text-primary);
  margin-bottom: 20px;
  font-variation-settings: 'opsz' 144, 'SOFT' 30;
}

.editorial-headline em {
  font-style: italic;
  font-weight: 400;
  color: var(--bbc-red);
  font-variation-settings: 'opsz' 144, 'SOFT' 80;
}

.editorial-headline .dropcap {
  display: inline-block;
  font-size: 1.2em;
  line-height: 0.8;
  margin-right: 4px;
}

.editorial-deck {
  font-family: var(--font-display);
  font-size: 19px;
  font-weight: 400;
  line-height: 1.5;
  color: var(--text-secondary);
  max-width: 720px;
  margin-bottom: 28px;
  font-style: italic;
  letter-spacing: -0.3px;
}

.editorial-byline {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 0;
  border-top: 1px solid var(--border-thin);
  border-bottom: 1px solid var(--border-thin);
  margin-bottom: 24px;
}

.editorial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.author-avatar {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--bbc-red);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  font-weight: 800;
  font-size: 13px;
  color: white;
  letter-spacing: -0.5px;
}

.author-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.author-name {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: -0.2px;
}

.author-role {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-tertiary);
  letter-spacing: 1.5px;
  text-transform: uppercase;
}

.editorial-time {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-tertiary);
  letter-spacing: 1.5px;
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: 8px;
}

.editorial-time::before {
  content: '';
  width: 6px;
  height: 6px;
  background: var(--bbc-red);
  border-radius: 50%;
  animation: live-pulse 1.5s ease-in-out infinite;
}

.editorial-side {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.side-card {
  background: var(--bbc-dark-grey);
  border: 1px solid var(--border-thin);
  padding: 20px;
  position: relative;
}

.side-card-header {
  padding-bottom: 12px;
  margin-bottom: 14px;
  border-bottom: 2px solid var(--bbc-red);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.side-card-title {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2.5px;
  color: var(--text-primary);
  text-transform: uppercase;
}

.side-card-action {
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 1.5px;
  color: var(--bbc-red);
  text-transform: uppercase;
  cursor: pointer;
}

.side-card-action:hover { text-decoration: underline; }

.markets-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.market-row {
  display: grid;
  grid-template-columns: 60px 1fr auto auto;
  align-items: center;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px solid var(--border-thin);
}

.market-row:last-child { border-bottom: none; }

.market-symbol {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--text-primary);
}

.market-name {
  font-size: 12px;
  color: var(--text-tertiary);
  font-weight: 500;
}

.market-value {
  font-family: var(--font-mono);
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
  text-align: right;
}

.market-change {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  padding: 2px 6px;
  border-radius: 2px;
  text-align: right;
  min-width: 60px;
}

.market-change.up { color: var(--success); background: rgba(0,176,79,0.1); }
.market-change.down { color: var(--bbc-red-bright); background: rgba(187,25,25,0.15); }

.breaking-stories {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.breaking-story {
  display: flex;
  gap: 14px;
  cursor: pointer;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--border-thin);
  transition: opacity 0.2s ease;
}

.breaking-story:last-child { border-bottom: none; padding-bottom: 0; }
.breaking-story:hover { opacity: 0.75; }

.story-number {
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 900;
  color: var(--bbc-red);
  line-height: 1;
  flex-shrink: 0;
  font-variation-settings: 'opsz' 144, 'WONK' 1;
  letter-spacing: -2px;
  min-width: 36px;
}

.story-content { flex: 1; min-width: 0; }

.story-cat {
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 1.8px;
  color: var(--bbc-red);
  text-transform: uppercase;
  font-weight: 700;
  margin-bottom: 5px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.story-cat .live {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--bbc-red);
  font-weight: 700;
}

.story-cat .live::before {
  content: '';
  width: 5px;
  height: 5px;
  background: var(--live-red);
  border-radius: 50%;
  animation: live-pulse 1.3s ease-in-out infinite;
}

.story-title {
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.2px;
  color: var(--text-primary);
  margin-bottom: 5px;
}

.story-meta {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-tertiary);
  letter-spacing: 1px;
  text-transform: uppercase;
}

.live-comments {
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-height: 280px;
  overflow-y: auto;
}

.comment-row {
  display: flex;
  gap: 10px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border-thin);
  animation: commentSlideIn 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

.comment-row:last-child { border-bottom: none; padding-bottom: 0; }

@keyframes commentSlideIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.comment-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 800;
  color: white;
  flex-shrink: 0;
}

.comment-body { flex: 1; min-width: 0; }

.comment-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 3px;
}

.comment-name {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-primary);
}

.comment-time {
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--text-tertiary);
  letter-spacing: 0.5px;
}

.comment-text {
  font-size: 12px;
  line-height: 1.45;
  color: var(--text-secondary);
}

.stats-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: var(--border-thin);
}

.stat-cell {
  background: var(--bbc-dark-grey);
  padding: 14px 12px;
}

.stat-cell-label {
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 2px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  margin-bottom: 6px;
}

.stat-cell-value {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1;
}

.stat-cell-sub {
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--success);
  letter-spacing: 1px;
  margin-top: 4px;
  display: flex;
  align-items: center;
  gap: 4px;
}

.stat-cell-sub.down { color: var(--bbc-red-bright); }

.editorial-stats-row {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 0;
  margin-bottom: 40px;
  border-top: 1px solid var(--border-thin);
  border-bottom: 1px solid var(--border-thin);
  background: var(--bbc-near-black);
}

.editorial-stat {
  padding: 22px 24px;
  border-right: 1px solid var(--border-thin);
  position: relative;
}

.editorial-stat:last-child { border-right: none; }

.editorial-stat-label {
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 2.5px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  margin-bottom: 8px;
}

.editorial-stat-value {
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1;
  display: flex;
  align-items: baseline;
  gap: 10px;
  font-variation-settings: 'opsz' 100;
}

.editorial-stat-trend {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 2px;
  letter-spacing: 1px;
}

.editorial-stat-trend.up { color: var(--success); background: rgba(0,176,79,0.1); }
.editorial-stat-trend.live { color: var(--bbc-red); background: rgba(187,25,25,0.12); display: inline-flex; align-items: center; gap: 4px; }

.editorial-stat-trend.live::before {
  content: '';
  width: 5px;
  height: 5px;
  background: var(--bbc-red);
  border-radius: 50%;
  animation: live-pulse 1.3s ease-in-out infinite;
}

.section-block {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  margin-bottom: 60px;
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 26px;
  gap: 16px;
  padding-bottom: 16px;
  border-bottom: 4px solid var(--bbc-red);
}

.section-title-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.section-eyebrow {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 3px;
  color: var(--bbc-red);
  text-transform: uppercase;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
}

.section-eyebrow::before {
  content: '';
  width: 24px;
  height: 2px;
  background: var(--bbc-red);
}

.section-title {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 42px;
  letter-spacing: -1.5px;
  line-height: 1;
  color: var(--text-primary);
  font-variation-settings: 'opsz' 144, 'SOFT' 50;
}

.section-title em {
  font-style: italic;
  font-weight: 400;
  color: var(--bbc-red);
  font-variation-settings: 'opsz' 144, 'SOFT' 80, 'WONK' 1;
}

.section-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.section-action-btn {
  padding: 9px 14px;
  background: var(--bbc-medium-grey);
  border-radius: 3px;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  letter-spacing: 1.5px;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.2s ease;
  display: flex;
  align-items: center;
  gap: 7px;
}

.section-action-btn:hover {
  background: var(--bbc-light-grey);
  color: var(--text-primary);
}

.section-action-btn.active {
  background: var(--bbc-red);
  color: white;
}

.section-action-btn svg { width: 13px; height: 13px; }

.section-row-categories {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 22px;
  scrollbar-width: none;
}

.section-row-categories::-webkit-scrollbar { display: none; }

.cat-pill {
  background: var(--bbc-medium-grey);
  color: var(--text-secondary);
  padding: 10px 18px;
  border-radius: 100px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.5px;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.2s ease;
  border: 1px solid transparent;
  display: flex;
  align-items: center;
  gap: 7px;
}

.cat-pill:hover {
  color: var(--text-primary);
  background: var(--bbc-light-grey);
}

.cat-pill.active {
  background: var(--bbc-red);
  color: white;
  border-color: var(--bbc-red-bright);
}

.cat-pill-count {
  font-family: var(--font-mono);
  font-size: 10px;
  background: rgba(0,0,0,0.3);
  padding: 1px 7px;
  border-radius: 10px;
}

.cat-pill.active .cat-pill-count { background: rgba(255,255,255,0.25); }

.channels-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 16px;
}

.channels-grid.wide {
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
}

.channel-card {
  background: var(--bbc-dark-grey);
  border: 1px solid var(--border-thin);
  border-radius: 3px;
  overflow: hidden;
  cursor: pointer;
  transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  animation: fadeUp 0.6s cubic-bezier(0.4, 0, 0.2, 1) backwards;
}

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

.channel-card:hover {
  transform: translateY(-4px);
  border-color: var(--bbc-red);
  box-shadow: var(--shadow-lg), 0 0 0 1px var(--bbc-red);
}

.channel-thumb {
  position: relative;
  width: 100%;
  padding-bottom: 56.25%;
  overflow: hidden;
  background: var(--bbc-medium-grey);
}

.channel-thumb-fallback {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  font-weight: 900;
  font-size: 42px;
  letter-spacing: -2px;
  color: white;
  text-shadow: 0 4px 24px rgba(0,0,0,0.6);
}

.channel-thumb-fallback::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 30% 20%, rgba(255,255,255,0.18) 0%, transparent 50%),
    linear-gradient(180deg, transparent 40%, rgba(0,0,0,0.75) 100%);
}

.live-tag {
  position: absolute;
  top: 10px;
  left: 10px;
  background: var(--bbc-red);
  color: white;
  padding: 5px 9px;
  border-radius: 2px;
  font-family: var(--font-sans);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.2px;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 5px;
}

.live-tag::before {
  content: '';
  width: 6px;
  height: 6px;
  background: white;
  border-radius: 50%;
  animation: live-pulse 1.2s ease-in-out infinite;
}

.featured-tag {
  position: absolute;
  top: 10px;
  right: 10px;
  background: var(--bbc-black);
  border: 1px solid var(--bbc-red);
  color: var(--bbc-red);
  padding: 4px 8px;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.5px;
  z-index: 3;
  text-transform: uppercase;
}

.viewers-tag {
  position: absolute;
  bottom: 10px;
  left: 10px;
  background: rgba(0,0,0,0.75);
  backdrop-filter: blur(6px);
  color: white;
  padding: 4px 8px;
  border-radius: 2px;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.5px;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 5px;
}

.viewers-tag::before {
  content: '';
  width: 5px;
  height: 5px;
  background: var(--live-red);
  border-radius: 50%;
  animation: live-pulse 1.5s ease-in-out infinite;
}

.quality-tag {
  position: absolute;
  bottom: 10px;
  right: 10px;
  background: rgba(0,0,0,0.7);
  color: white;
  padding: 4px 7px;
  border-radius: 2px;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1px;
  z-index: 3;
}

.play-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0,0,0,0.55);
  opacity: 0;
  transition: opacity 0.3s ease;
  z-index: 2;
}

.channel-card:hover .play-overlay { opacity: 1; }

.play-icon {
  width: 60px;
  height: 60px;
  background: var(--bbc-red);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 8px 32px var(--shadow-red);
  transform: scale(0.75);
  transition: transform 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.channel-card:hover .play-icon { transform: scale(1); }

.play-icon::after {
  content: '';
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 9px 0 9px 15px;
  border-color: transparent transparent transparent white;
  margin-left: 3px;
}

.channel-info {
  padding: 14px 16px;
  position: relative;
}

.channel-info-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
}

.channel-name {
  font-family: var(--font-sans);
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 1;
  min-width: 0;
}

.channel-fav-btn {
  background: none;
  width: 26px;
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: 50%;
  transition: all 0.2s ease;
}

.channel-fav-btn:hover { background: var(--bbc-medium-grey); }

.channel-fav-btn svg {
  width: 14px;
  height: 14px;
  stroke: var(--text-tertiary);
  fill: none;
  transition: all 0.2s ease;
}

.channel-fav-btn.active svg {
  stroke: var(--bbc-red);
  fill: var(--bbc-red);
}

.channel-meta-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.channel-category {
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 1.5px;
}

.channel-quality {
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--text-secondary);
  font-weight: 700;
  letter-spacing: 1px;
  padding: 2px 6px;
  border: 1px solid var(--border-medium);
  border-radius: 2px;
}

.featured-row {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 16px;
  margin-bottom: 24px;
}

.featured-card-main {
  background: var(--bbc-dark-grey);
  border: 1px solid var(--border-thin);
  overflow: hidden;
  position: relative;
  cursor: pointer;
  transition: transform 0.3s ease;
  min-height: 360px;
}

.featured-card-main:hover { transform: translateY(-4px); }

.featured-card-thumb {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 360px;
  overflow: hidden;
}

.featured-card-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  font-weight: 900;
  font-size: 80px;
  letter-spacing: -4px;
  color: white;
  text-shadow: 0 8px 40px rgba(0,0,0,0.7);
}

.featured-card-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 30%, rgba(0,0,0,0.9) 100%);
}

.featured-card-content {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 28px 32px;
  z-index: 2;
}

.featured-card-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--bbc-red);
  color: white;
  padding: 5px 12px;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 14px;
}

.featured-card-tag::before {
  content: '';
  width: 6px;
  height: 6px;
  background: white;
  border-radius: 50%;
  animation: live-pulse 1.2s ease-in-out infinite;
}

.featured-card-title {
  font-family: var(--font-display);
  font-size: 36px;
  font-weight: 700;
  letter-spacing: -1.2px;
  line-height: 1;
  color: white;
  margin-bottom: 8px;
}

.featured-card-sub {
  font-size: 14px;
  color: rgba(255,255,255,0.85);
  font-weight: 500;
}

.featured-card-side {
  background: var(--bbc-dark-grey);
  border: 1px solid var(--border-thin);
  overflow: hidden;
  cursor: pointer;
  position: relative;
  display: flex;
  flex-direction: column;
  transition: transform 0.3s ease;
}

.featured-card-side:hover { transform: translateY(-4px); }

.featured-card-side-thumb {
  position: relative;
  width: 100%;
  padding-bottom: 56.25%;
  overflow: hidden;
}

.featured-card-side-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  font-weight: 900;
  font-size: 38px;
  letter-spacing: -1.5px;
  color: white;
}

.featured-card-side-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(0,0,0,0.7) 100%);
}

.featured-card-side-content {
  padding: 14px 16px;
}

.featured-card-side-cat {
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 1.5px;
  color: var(--bbc-red);
  text-transform: uppercase;
  font-weight: 700;
  margin-bottom: 4px;
}

.featured-card-side-title {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 700;
  letter-spacing: -0.4px;
  line-height: 1.15;
  color: var(--text-primary);
  margin-bottom: 6px;
}

.featured-card-side-meta {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-tertiary);
  letter-spacing: 1px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.row-section {
  margin-bottom: 50px;
}

.row-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 18px;
  gap: 16px;
}

.row-section-title-block {
  display: flex;
  align-items: baseline;
  gap: 14px;
}

.row-section-eyebrow {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2.5px;
  color: var(--bbc-red);
  text-transform: uppercase;
  padding: 3px 8px;
  background: rgba(187,25,25,0.12);
  border-left: 2px solid var(--bbc-red);
}

.row-section-title {
  font-family: var(--font-display);
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.8px;
  color: var(--text-primary);
  line-height: 1;
}

.row-section-title em {
  font-style: italic;
  font-weight: 400;
  color: var(--bbc-red);
}

.row-section-more {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 1.5px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: color 0.2s ease;
}

.row-section-more:hover { color: var(--bbc-red); }

.row-section-more svg { width: 12px; height: 12px; }

.row-carousel {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding-bottom: 12px;
  scrollbar-width: none;
}

.row-carousel::-webkit-scrollbar { display: none; }

.row-card {
  flex: 0 0 280px;
  background: var(--bbc-dark-grey);
  border: 1px solid var(--border-thin);
  border-radius: 3px;
  overflow: hidden;
  cursor: pointer;
  transition: all 0.3s ease;
}

.row-card:hover {
  transform: translateY(-3px);
  border-color: var(--bbc-red);
}

.row-card-thumb {
  position: relative;
  width: 100%;
  padding-bottom: 56.25%;
}

.row-card-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  font-weight: 900;
  font-size: 38px;
  letter-spacing: -1.5px;
  color: white;
}

.row-card-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(0,0,0,0.6) 100%);
}

.row-card-info {
  padding: 12px 14px;
}

.row-card-name {
  font-size: 14px;
  font-weight: 700;
  letter-spacing: -0.2px;
  margin-bottom: 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.row-card-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.row-card-cat {
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 1.5px;
}

.row-card-viewers {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--bbc-red);
  font-weight: 700;
  letter-spacing: 0.5px;
  display: flex;
  align-items: center;
  gap: 4px;
}

.row-card-viewers::before {
  content: '';
  width: 5px;
  height: 5px;
  background: var(--live-red);
  border-radius: 50%;
  animation: live-pulse 1.5s ease-in-out infinite;
}

.toast-container {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  gap: 10px;
  pointer-events: none;
}

.toast {
  background: var(--bbc-dark-grey);
  border: 1px solid var(--border-medium);
  border-left: 3px solid var(--bbc-red);
  padding: 14px 18px;
  border-radius: 3px;
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 280px;
  max-width: 360px;
  animation: toast-in 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  pointer-events: auto;
}

.toast.exit { animation: toast-out 0.3s cubic-bezier(0.4, 0, 1, 1) forwards; }

@keyframes toast-in {
  from { opacity: 0; transform: translateX(100%); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes toast-out {
  to { opacity: 0; transform: translateX(100%); }
}

.toast-icon {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--bbc-red);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.toast-icon svg { width: 16px; height: 16px; color: white; }
.toast-content { flex: 1; }

.toast-title {
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 2px;
  letter-spacing: -0.2px;
}

.toast-msg {
  font-size: 11px;
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  letter-spacing: 0.5px;
}

.mini-player {
  position: fixed;
  bottom: 24px;
  right: 24px;
  width: 360px;
  background: var(--bbc-black);
  border: 1px solid var(--border-bright);
  border-radius: 3px;
  overflow: hidden;
  box-shadow: var(--shadow-xl);
  z-index: 800;
  opacity: 0;
  visibility: hidden;
  transform: translateY(40px) scale(0.95);
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

.mini-player.visible {
  opacity: 1;
  visibility: visible;
  transform: translateY(0) scale(1);
}

.mini-player-frame {
  position: relative;
  width: 100%;
  padding-bottom: 56.25%;
  background: #000;
}

.mini-player-frame iframe {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
}

.mini-player-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  background: var(--bbc-dark-grey);
  border-top: 2px solid var(--bbc-red);
}

.mini-player-info {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.mini-player-name {
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.mini-player-status {
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--bbc-red);
  font-weight: 700;
  letter-spacing: 1px;
  display: flex;
  align-items: center;
  gap: 4px;
}

.mini-player-status::before {
  content: '';
  width: 5px;
  height: 5px;
  background: var(--bbc-red);
  border-radius: 50%;
  animation: live-pulse 1.2s ease-in-out infinite;
}

.mini-player-actions {
  display: flex;
  gap: 4px;
}

.mini-player-btn {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 3px;
  cursor: pointer;
  transition: background 0.15s ease;
}

.mini-player-btn:hover { background: var(--bbc-medium-grey); }
.mini-player-btn svg { width: 12px; height: 12px; }

body.cinema-active .top-bar,
body.cinema-active .site-header,
body.cinema-active .epg-bar,
body.cinema-active .live-banner,
body.cinema-active .channel-list-side,
body.cinema-active .editorial-section,
body.cinema-active .section-block,
body.cinema-active .row-section,
body.cinema-active .site-footer {
  opacity: 0.15;
  filter: blur(2px);
  transition: opacity 0.5s ease, filter 0.5s ease;
}

body.cinema-active .player-master {
  position: relative;
  z-index: 500;
  box-shadow: 0 0 100px rgba(0,0,0,0.9), var(--shadow-red-glow);
}

body.cinema-active::before {
  content: '';
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.75);
  z-index: 400;
  pointer-events: none;
}

.site-footer {
  background: var(--bbc-near-black);
  border-top: 4px solid var(--bbc-red);
  padding: 60px 24px 32px;
  margin-top: 80px;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.8fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 40px;
}

.footer-col h4 {
  font-family: var(--font-sans);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: var(--text-primary);
  margin-bottom: 18px;
  padding-bottom: 10px;
  border-bottom: 2px solid var(--bbc-red);
  display: inline-block;
}

.footer-brand-block {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 18px;
}

.footer-brand-block .logo-block {
  font-size: 18px;
  padding: 7px 9px;
}

.footer-desc {
  font-family: var(--font-display);
  font-size: 14px;
  font-style: italic;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 20px;
  max-width: 380px;
  letter-spacing: -0.2px;
}

.footer-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  max-width: 320px;
  margin-top: 16px;
}

.footer-stat-cell {
  padding: 10px 12px;
  background: var(--bbc-dark-grey);
  border-left: 2px solid var(--bbc-red);
}

.footer-stat-label {
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 1.5px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  margin-bottom: 4px;
}

.footer-stat-value {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1;
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: 11px;
}

.footer-link {
  font-size: 13px;
  color: var(--text-secondary);
  transition: color 0.2s ease;
  display: flex;
  align-items: center;
  gap: 8px;
}

.footer-link::before {
  content: '';
  width: 4px;
  height: 4px;
  background: var(--bbc-red);
  opacity: 0;
  transition: opacity 0.2s ease;
}

.footer-link:hover {
  color: var(--bbc-red);
}

.footer-link:hover::before {
  opacity: 1;
}

.footer-bottom {
  max-width: var(--max-width);
  margin: 0 auto;
  padding-top: 28px;
  border-top: 1px solid var(--border-thin);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-copy {
  font-size: 11px;
  color: var(--text-muted);
  font-family: var(--font-mono);
  letter-spacing: 0.5px;
}

.footer-copy strong { color: var(--text-secondary); }

.footer-tagline {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 16px;
  color: var(--text-tertiary);
  letter-spacing: -0.3px;
}

.footer-social {
  display: flex;
  gap: 8px;
}

.footer-social-btn {
  width: 32px;
  height: 32px;
  background: var(--bbc-medium-grey);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 3px;
  transition: all 0.2s ease;
}

.footer-social-btn:hover { background: var(--bbc-red); }

.footer-social-btn svg {
  width: 14px;
  height: 14px;
  color: var(--text-secondary);
}

.footer-social-btn:hover svg { color: white; }

.mobile-bottom-nav {
  display: none;
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: rgba(0,0,0,0.96);
  backdrop-filter: blur(24px);
  border-top: 1px solid var(--border-medium);
  padding: 10px 8px calc(10px + env(safe-area-inset-bottom));
  z-index: 700;
  justify-content: space-around;
  align-items: center;
}

.mobile-nav-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 6px 10px;
  cursor: pointer;
  flex: 1;
  max-width: 80px;
  position: relative;
  border-radius: 8px;
  transition: background 0.2s ease;
}

.mobile-nav-item:active { background: var(--bbc-medium-grey); }

.mobile-nav-icon {
  width: 26px;
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-tertiary);
  transition: color 0.2s ease;
}

.mobile-nav-icon svg { width: 24px; height: 24px; }

.mobile-nav-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-tertiary);
  letter-spacing: 0.3px;
  transition: color 0.2s ease;
}

.mobile-nav-item.active .mobile-nav-icon,
.mobile-nav-item.active .mobile-nav-label {
  color: var(--bbc-red);
}

.mobile-nav-item.active::before {
  content: '';
  position: absolute;
  top: -1px;
  left: 30%;
  right: 30%;
  height: 3px;
  background: var(--bbc-red);
  border-radius: 0 0 2px 2px;
}

.mobile-nav-item .badge {
  position: absolute;
  top: 2px;
  right: 8px;
  background: var(--bbc-red);
  color: white;
  font-size: 9px;
  font-weight: 700;
  padding: 1px 5px;
  border-radius: 10px;
  min-width: 16px;
  text-align: center;
}

.pull-refresh {
  position: fixed;
  top: -60px;
  left: 0;
  right: 0;
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-tertiary);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 1px;
  transition: top 0.3s ease;
  z-index: 50;
  background: var(--bbc-near-black);
}

.pull-refresh.active { top: 0; }

.pull-refresh-spinner {
  width: 20px;
  height: 20px;
  border: 2px solid var(--border-medium);
  border-top-color: var(--bbc-red);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
  margin-right: 10px;
}

@keyframes spin { to { transform: rotate(360deg); } }

.view-favorites,
.view-history,
.view-all {
  display: none;
}

.view-favorites.active,
.view-history.active,
.view-all.active {
  display: block;
}

.no-favorites {
  text-align: center;
  padding: 80px 20px;
  color: var(--text-tertiary);
}

.no-favorites-icon {
  font-size: 64px;
  opacity: 0.3;
  margin-bottom: 16px;
  font-family: var(--font-display);
}

.no-favorites-title {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 28px;
  color: var(--text-secondary);
  margin-bottom: 8px;
  letter-spacing: -0.5px;
}

.no-favorites-sub {
  font-size: 12px;
  font-family: var(--font-mono);
  letter-spacing: 1.5px;
  text-transform: uppercase;
}

.context-menu {
  position: fixed;
  background: var(--bbc-dark-grey);
  border: 1px solid var(--border-medium);
  border-radius: 3px;
  padding: 6px;
  min-width: 200px;
  z-index: 900;
  box-shadow: var(--shadow-xl);
  opacity: 0;
  visibility: hidden;
  transform: scale(0.95);
  transition: all 0.15s ease;
}

.context-menu.open {
  opacity: 1;
  visibility: visible;
  transform: scale(1);
}

.context-menu-item {
  padding: 10px 14px;
  font-size: 13px;
  color: var(--text-secondary);
  cursor: pointer;
  border-radius: 2px;
  display: flex;
  align-items: center;
  gap: 10px;
  transition: background 0.15s ease;
}

.context-menu-item:hover {
  background: var(--bbc-medium-grey);
  color: var(--text-primary);
}

.context-menu-item svg {
  width: 14px;
  height: 14px;
  opacity: 0.7;
}

.context-menu-divider {
  height: 1px;
  background: var(--border-thin);
  margin: 4px 0;
}

@media (max-width: 1300px) {
  .priority-section {
    grid-template-columns: 1fr 340px;
  }
  .editorial-grid {
    grid-template-columns: 1.5fr 1fr;
    gap: 28px;
  }
}

@media (max-width: 1100px) {
  .priority-section {
    grid-template-columns: 1fr;
  }
  .channel-list-side {
    position: static;
    max-height: 460px;
    min-height: auto;
  }
  .editorial-grid {
    grid-template-columns: 1fr;
  }
  .editorial-stats-row {
    grid-template-columns: repeat(3, 1fr);
  }
  .editorial-stat:nth-child(3) { border-right: none; }
  .editorial-stat:nth-child(n+4) { border-top: 1px solid var(--border-thin); }
  .main-nav { display: none; }
  .footer-inner { grid-template-columns: 1.5fr 1fr 1fr; }
  .featured-row {
    grid-template-columns: 1fr 1fr;
  }
  .featured-card-main {
    grid-column: span 2;
    min-height: 280px;
  }
  .featured-card-main .featured-card-thumb { min-height: 280px; }
  .featured-card-bg { font-size: 56px; }
}

@media (max-width: 768px) {
  :root {
    --header-height: 64px;
  }

  body {
    padding-bottom: calc(var(--bottom-nav-height) + env(safe-area-inset-bottom));
  }

  .top-bar { padding: 5px 0; }
  .top-bar-inner { padding: 0 14px; gap: 10px; flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; }
  .top-bar-inner::-webkit-scrollbar { display: none; }
  .top-bar-left, .top-bar-right { gap: 10px; flex-shrink: 0; }
  .top-bar-item { font-size: 10px; }
  .top-bar-clock { font-size: 11px; }

  .header-inner {
    padding: 12px 14px;
    gap: 10px;
    flex-wrap: wrap;
  }

  .logo-block {
    padding: 7px 9px;
    font-size: 17px;
  }

  .logo-meta {
    margin-left: 10px;
    padding-left: 10px;
  }

  .logo-meta-title { font-size: 12px; }
  .logo-meta-sub { font-size: 8px; letter-spacing: 2px; }

  .search-box {
    order: 3;
    width: 100%;
    flex-basis: 100%;
  }

  .search-input { padding: 9px 14px 9px 34px; font-size: 13px; }

  .header-right {
    gap: 8px;
  }

  .country-btn { padding: 7px 11px; font-size: 12px; }
  .country-btn span:not(.country-flag) { display: none; }

  .epg-bar { padding: 9px 0; }
  .epg-inner { padding: 0 14px; gap: 12px; }
  .epg-label { font-size: 10px; padding-right: 12px; }
  .epg-items { gap: 18px; }
  .epg-program { font-size: 12px; }
  .epg-channel { font-size: 10px; }

  .priority-layout-container { padding: 14px 14px 0; }

  .live-banner {
    padding: 8px 12px;
    gap: 10px;
    flex-wrap: wrap;
  }

  .live-banner-text {
    font-size: 13px;
    width: 100%;
    order: 3;
    white-space: normal;
    line-height: 1.3;
  }

  .live-banner-tag {
    padding: 4px 9px;
    font-size: 9px;
  }

  .live-banner-right {
    width: 100%;
    justify-content: space-between;
    order: 2;
    font-size: 9px;
  }

  .priority-section {
    gap: 12px;
    margin-bottom: 24px;
  }

  .player-master {
    border-left: none;
    border-right: none;
    margin: 0 -14px;
    width: calc(100% + 28px);
  }

  .player-controls {
    padding: 11px 14px;
    gap: 8px;
  }

  .player-ctrl-btn { width: 34px; height: 34px; }
  .player-ctrl-btn.primary { width: 40px; height: 40px; }
  .player-ctrl-btn:hover::after { display: none; }

  .player-time-block {
    font-size: 10px;
    gap: 6px;
    margin-left: 0;
  }

  .player-time-block .time-val { font-size: 11px; }

  .player-volume { display: none; }

  .player-info-bar { padding: 14px 16px; }
  .player-channel-title { font-size: 24px; letter-spacing: -0.7px; }
  .player-channel-desc { font-size: 13px; }
  .player-info-meta-row { font-size: 9px; letter-spacing: 1.5px; gap: 7px; }
  .player-meta-tag { padding: 3px 8px; }
  .player-action-row { gap: 6px; margin-top: 12px; padding-top: 12px; }
  .player-action { padding: 8px 11px; font-size: 10px; }

  .player-signal { padding: 5px 9px; top: 12px; right: 12px; }
  .signal-text { font-size: 9px; }
  .signal-bars { height: 12px; }

  .player-watermark { top: 12px; left: 12px; }
  .player-watermark-logo { font-size: 9px; padding: 3px 6px; }

  .channel-list-side {
    margin: 0 -14px;
    width: calc(100% + 28px);
    border-left: none;
    border-right: none;
    max-height: 540px;
  }

  .channel-list-header { padding: 14px 16px 12px; }
  .channel-list-title { font-size: 16px; }
  .channel-list-tabs { padding: 0 4px; }
  .list-tab { padding: 11px 12px; font-size: 10px; }
  .list-channel-thumb { width: 44px; height: 44px; font-size: 12px; }
  .list-channel-name { font-size: 12px; }
  .list-channel-info { font-size: 9px; }

  .editorial-section {
    padding: 24px 14px;
  }

  .editorial-grid {
    gap: 30px;
    margin-bottom: 36px;
  }

  .editorial-tag {
    font-size: 9px;
    padding: 5px 10px;
    margin-bottom: 14px;
  }

  .editorial-headline {
    font-size: 36px;
    letter-spacing: -1.4px;
    line-height: 1.02;
  }

  .editorial-deck {
    font-size: 15px;
    line-height: 1.5;
  }

  .editorial-byline { padding: 12px 0; margin-bottom: 18px; }
  .author-avatar { width: 32px; height: 32px; font-size: 11px; }
  .author-name { font-size: 12px; }
  .author-role { font-size: 9px; }
  .editorial-time { font-size: 10px; }

  .side-card { padding: 16px; }
  .side-card-title { font-size: 10px; }

  .editorial-stats-row {
    grid-template-columns: repeat(2, 1fr);
  }

  .editorial-stat {
    padding: 16px;
    border-right: 1px solid var(--border-thin);
    border-bottom: 1px solid var(--border-thin);
  }
  .editorial-stat:nth-child(2n) { border-right: none; }
  .editorial-stat:nth-child(n+4) { border-bottom: none; }
  .editorial-stat-value { font-size: 24px; }
  .editorial-stat-label { font-size: 8px; letter-spacing: 2px; }

  .section-block {
    padding: 0 14px;
    margin-bottom: 36px;
  }

  .section-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
    padding-bottom: 12px;
    border-bottom-width: 3px;
  }

  .section-eyebrow { font-size: 9px; }
  .section-title { font-size: 28px; letter-spacing: -0.8px; }
  .section-actions { width: 100%; overflow-x: auto; scrollbar-width: none; }
  .section-actions::-webkit-scrollbar { display: none; }
  .section-action-btn { padding: 7px 12px; font-size: 10px; flex-shrink: 0; }

  .section-row-categories { padding-bottom: 16px; gap: 6px; }
  .cat-pill { padding: 8px 14px; font-size: 11px; }

  .channels-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
  }

  .channel-info { padding: 10px 12px; }
  .channel-name { font-size: 13px; letter-spacing: -0.2px; }
  .channel-category { font-size: 8px; }
  .channel-quality { font-size: 8px; padding: 1px 5px; }
  .channel-thumb-fallback { font-size: 28px; }
  .live-tag { font-size: 9px; padding: 3px 6px; top: 8px; left: 8px; }
  .featured-tag { font-size: 8px; padding: 3px 6px; top: 8px; right: 8px; }
  .viewers-tag { font-size: 9px; padding: 3px 6px; bottom: 8px; left: 8px; }
  .quality-tag { font-size: 8px; padding: 3px 5px; bottom: 8px; right: 8px; }
  .play-icon { width: 50px; height: 50px; }
  .play-icon::after { border-width: 8px 0 8px 12px; }

  .featured-row {
    grid-template-columns: 1fr;
    gap: 12px;
    padding: 0 14px;
  }

  .featured-card-main {
    grid-column: span 1;
    min-height: 240px;
  }

  .featured-card-main .featured-card-thumb { min-height: 240px; }
  .featured-card-bg { font-size: 48px; }
  .featured-card-title { font-size: 26px; letter-spacing: -0.8px; }
  .featured-card-content { padding: 20px 22px; }

  .row-section { margin-bottom: 36px; padding: 0 14px; }
  .row-section-title { font-size: 22px; letter-spacing: -0.5px; }
  .row-section-eyebrow { font-size: 9px; padding: 2px 6px; }
  .row-card { flex: 0 0 220px; }
  .row-card-name { font-size: 13px; }

  .mini-player {
    width: calc(100% - 28px);
    right: 14px;
    bottom: calc(var(--bottom-nav-height) + 14px + env(safe-area-inset-bottom));
    max-width: 320px;
  }

  .toast-container {
    bottom: calc(var(--bottom-nav-height) + 16px + env(safe-area-inset-bottom));
    right: 14px;
    left: 14px;
  }

  .toast { min-width: 0; max-width: 100%; }

  .site-footer { padding: 40px 14px 28px; margin-top: 40px; }
  .footer-inner {
    grid-template-columns: 1fr 1fr;
    gap: 28px;
    margin-bottom: 28px;
  }
  .footer-col:first-child {
    grid-column: span 2;
  }
  .footer-bottom { 
    flex-direction: column;
    align-items: flex-start;
    gap: 14px;
  }
  .footer-tagline { font-size: 14px; }

  .mobile-bottom-nav { display: flex; }

  .splash-text { font-size: 42px; }
  .splash-bar { height: 44px; }
  .splash-loader { width: 240px; }
}

@media (max-width: 480px) {
  .editorial-headline { font-size: 30px; }
  .editorial-stat-value { font-size: 20px; }
  .channels-grid { gap: 8px; }
  .channel-thumb-fallback { font-size: 24px; }
  .player-channel-title { font-size: 20px; }
  .section-title { font-size: 22px; }
  .top-bar-clock { font-size: 10px; }
  .footer-inner { grid-template-columns: 1fr; }
  .footer-col:first-child { grid-column: span 1; }
}

#sidebar-wrapper, .sidebar { display: none; }
.widget-content { color: var(--text-secondary); }
.hidden-section { display: none !important; }

/* ============================================
   NETFLIX-STYLE FEATURES
   ============================================ */

.hero-rotator {
  position: relative;
  width: 100%;
  margin: 0 auto 40px;
  max-width: var(--max-width);
  padding: 0 24px;
}

.hero-stage {
  position: relative;
  width: 100%;
  height: 480px;
  border-radius: 6px;
  overflow: hidden;
  background: var(--bbc-near-black);
  box-shadow: var(--shadow-xl);
}

.hero-slide {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity 1.2s cubic-bezier(0.4, 0, 0.2, 1);
  pointer-events: none;
}

.hero-slide.active {
  opacity: 1;
  pointer-events: auto;
}

.hero-slide-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  padding: 60px;
  font-family: var(--font-sans);
  font-weight: 900;
  font-size: 200px;
  letter-spacing: -8px;
  color: rgba(255,255,255,0.04);
  line-height: 0.85;
  overflow: hidden;
}

.hero-slide-bg::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 70% 30%, var(--hero-color, var(--bbc-red)) 0%, transparent 50%),
    linear-gradient(90deg, rgba(0,0,0,0.92) 0%, rgba(0,0,0,0.7) 40%, rgba(0,0,0,0.3) 70%, transparent 100%);
  opacity: 0.85;
}

.hero-slide-content {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 50%;
  padding: 50px 60px;
  z-index: 5;
}

.hero-slide-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 12px;
  background: var(--bbc-red);
  color: white;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  margin-bottom: 16px;
  border-radius: 2px;
}

.hero-slide-eyebrow::before {
  content: '';
  width: 6px;
  height: 6px;
  background: white;
  border-radius: 50%;
  animation: live-pulse 1.2s ease-in-out infinite;
}

.hero-slide-title {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 64px;
  letter-spacing: -2.5px;
  line-height: 0.95;
  color: white;
  margin-bottom: 14px;
  font-variation-settings: 'opsz' 144, 'SOFT' 30;
  text-shadow: 0 4px 20px rgba(0,0,0,0.5);
}

.hero-slide-desc {
  font-family: var(--font-display);
  font-size: 17px;
  font-style: italic;
  line-height: 1.5;
  color: rgba(255,255,255,0.92);
  margin-bottom: 20px;
  letter-spacing: -0.3px;
  max-width: 92%;
}

.hero-slide-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 26px;
  flex-wrap: wrap;
}

.hero-slide-meta-tag {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.8px;
  padding: 4px 10px;
  background: rgba(255,255,255,0.15);
  border-radius: 2px;
  color: white;
}

.hero-slide-meta-tag.match {
  background: var(--success);
  color: white;
}

.hero-slide-meta-tag.rating {
  background: white;
  color: var(--bbc-black);
}

.hero-slide-buttons {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.hero-btn {
  padding: 14px 28px;
  font-weight: 800;
  font-size: 13px;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  border-radius: 4px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  transition: all 0.25s ease;
}

.hero-btn-primary {
  background: white;
  color: var(--bbc-black);
}

.hero-btn-primary:hover {
  background: rgba(255,255,255,0.85);
  transform: translateY(-2px);
}

.hero-btn-primary svg { width: 18px; height: 18px; }

.hero-btn-secondary {
  background: rgba(109, 109, 110, 0.7);
  color: white;
  backdrop-filter: blur(8px);
}

.hero-btn-secondary:hover {
  background: rgba(109, 109, 110, 0.9);
}

.hero-indicators {
  position: absolute;
  bottom: 20px;
  right: 30px;
  display: flex;
  gap: 6px;
  z-index: 10;
}

.hero-indicator {
  width: 24px;
  height: 3px;
  background: rgba(255,255,255,0.3);
  cursor: pointer;
  transition: background 0.2s ease;
  border-radius: 1px;
}

.hero-indicator.active {
  background: var(--bbc-red);
}

.hero-indicator:hover { background: rgba(255,255,255,0.6); }

.hero-controls {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: rgba(0,0,0,0.5);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 10;
  opacity: 0;
  transition: opacity 0.3s ease, background 0.2s ease;
}

.hero-stage:hover .hero-controls { opacity: 1; }
.hero-controls:hover { background: var(--bbc-red); }
.hero-controls.prev { left: 16px; }
.hero-controls.next { right: 16px; }
.hero-controls svg { width: 20px; height: 20px; color: white; }

/* CONTINUE WATCHING */
.continue-section {
  margin-bottom: 40px;
}

.continue-card {
  position: relative;
  flex: 0 0 340px;
  background: var(--bbc-dark-grey);
  border-radius: 4px;
  overflow: hidden;
  cursor: pointer;
  transition: all 0.3s ease;
}

.continue-card:hover { transform: translateY(-3px); }

.continue-thumb {
  position: relative;
  width: 100%;
  padding-bottom: 56.25%;
}

.continue-thumb-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  font-weight: 900;
  font-size: 48px;
  letter-spacing: -2px;
  color: white;
}

.continue-thumb-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(0,0,0,0.8) 100%);
}

.continue-progress {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: rgba(255,255,255,0.25);
  z-index: 4;
}

.continue-progress-bar {
  position: absolute;
  inset: 0;
  background: var(--bbc-red);
  width: var(--progress, 35%);
}

.continue-card-info {
  padding: 12px 14px;
}

.continue-card-name {
  font-weight: 700;
  font-size: 14px;
  margin-bottom: 4px;
  letter-spacing: -0.2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.continue-card-time {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-tertiary);
  letter-spacing: 1px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.continue-card-time::before {
  content: '◷';
  color: var(--bbc-red);
}

.continue-card-play {
  position: absolute;
  bottom: 12px;
  right: 12px;
  width: 44px;
  height: 44px;
  background: var(--bbc-red);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 5;
  opacity: 0;
  transition: all 0.3s ease;
  box-shadow: 0 4px 16px var(--shadow-red);
}

.continue-card:hover .continue-card-play {
  opacity: 1;
  transform: scale(1.1);
}

.continue-card-play::after {
  content: '';
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 7px 0 7px 12px;
  border-color: transparent transparent transparent white;
  margin-left: 2px;
}

/* TOP 10 SECTION (Netflix-style numerais gigantes) */
.top10-section {
  margin-bottom: 50px;
}

.top10-carousel {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  padding: 24px 24px 30px;
  scrollbar-width: none;
}

.top10-carousel::-webkit-scrollbar { display: none; }

.top10-card {
  position: relative;
  flex: 0 0 220px;
  height: 200px;
  display: flex;
  align-items: flex-end;
  cursor: pointer;
  padding-left: 80px;
}

.top10-number {
  position: absolute;
  left: -30px;
  bottom: -32px;
  font-family: var(--font-sans);
  font-weight: 900;
  font-size: 240px;
  letter-spacing: -16px;
  line-height: 0.8;
  color: var(--bbc-near-black);
  -webkit-text-stroke: 3px var(--bbc-red);
  text-stroke: 3px var(--bbc-red);
  z-index: 1;
  pointer-events: none;
  transition: transform 0.3s ease, color 0.3s ease;
}

.top10-card:hover .top10-number {
  transform: scale(1.05);
  color: rgba(187, 25, 25, 0.15);
}

.top10-thumb {
  position: relative;
  width: 140px;
  height: 190px;
  border-radius: 4px;
  overflow: hidden;
  z-index: 2;
  transition: transform 0.3s ease;
}

.top10-card:hover .top10-thumb { transform: scale(1.06); }

.top10-thumb-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  font-weight: 900;
  font-size: 28px;
  color: white;
  text-align: center;
  padding: 12px;
  letter-spacing: -1px;
}

.top10-thumb-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(0,0,0,0.85) 100%);
}

.top10-card-overlay {
  position: absolute;
  inset: 0;
  z-index: 3;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 12px;
  pointer-events: none;
}

.top10-card-name {
  font-size: 12px;
  font-weight: 800;
  color: white;
  text-shadow: 0 2px 8px rgba(0,0,0,0.8);
  margin-bottom: 4px;
  letter-spacing: -0.2px;
  line-height: 1.1;
}

.top10-card-cat {
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 1.5px;
  color: rgba(255,255,255,0.85);
  text-transform: uppercase;
}

.top10-tag {
  position: absolute;
  top: 8px;
  right: 8px;
  background: var(--bbc-red);
  color: white;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 1.5px;
  padding: 3px 6px;
  border-radius: 2px;
  z-index: 4;
}

/* HOVER-EXPAND CARDS (Netflix-style) */
.netflix-row {
  margin-bottom: 50px;
  position: relative;
}

.netflix-row-header {
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.netflix-row-title {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.7px;
  color: var(--text-primary);
  display: flex;
  align-items: baseline;
  gap: 12px;
}

.netflix-row-title em {
  font-style: italic;
  color: var(--bbc-red);
  font-weight: 400;
}

.netflix-row-title .row-counter {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  color: var(--text-tertiary);
  letter-spacing: 1px;
  text-transform: uppercase;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.netflix-row:hover .row-counter { opacity: 1; }

.netflix-row-explore {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 2px;
  color: var(--bbc-red);
  text-transform: uppercase;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.netflix-row:hover .netflix-row-explore { opacity: 1; }
.netflix-row-explore svg { width: 11px; height: 11px; }

.netflix-row-track {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  padding: 30px 24px;
  scrollbar-width: none;
  scroll-behavior: smooth;
}

.netflix-row-track::-webkit-scrollbar { display: none; }

.netflix-card {
  position: relative;
  flex: 0 0 240px;
  height: 135px;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  overflow: visible;
  transform-origin: center center;
}

.netflix-card:first-child { transform-origin: left center; }
.netflix-card:last-child { transform-origin: right center; }

.netflix-card-inner {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 4px;
  overflow: hidden;
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.netflix-card-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  font-weight: 900;
  font-size: 32px;
  letter-spacing: -1px;
  color: white;
  text-shadow: 0 4px 16px rgba(0,0,0,0.4);
}

.netflix-card-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(0,0,0,0.5) 100%);
}

.netflix-card-live-tag {
  position: absolute;
  top: 10px;
  left: 10px;
  background: var(--bbc-red);
  color: white;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1.2px;
  padding: 3px 7px;
  border-radius: 2px;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 5px;
}

.netflix-card-live-tag::before {
  content: '';
  width: 5px;
  height: 5px;
  background: white;
  border-radius: 50%;
  animation: live-pulse 1.3s ease-in-out infinite;
}

.netflix-card-bottom {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 10px 12px;
  z-index: 3;
}

.netflix-card-name {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: -0.2px;
  color: white;
  text-shadow: 0 2px 8px rgba(0,0,0,0.8);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.netflix-card-meta-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 1px;
  color: rgba(255,255,255,0.85);
  text-transform: uppercase;
}

/* Card expandido ao hover */
.netflix-card:hover {
  z-index: 100;
  transform: scale(1.4) translateY(-10px);
  box-shadow: var(--shadow-xl);
}

.netflix-card-detail-popup {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--bbc-dark-grey);
  padding: 12px;
  border-radius: 0 0 4px 4px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.netflix-card:hover .netflix-card-detail-popup {
  opacity: 1;
  pointer-events: auto;
}

.netflix-card-detail-actions {
  display: flex;
  gap: 6px;
  margin-bottom: 8px;
}

.netflix-card-action-btn {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s ease;
}

.netflix-card-action-btn:hover { background: rgba(255,255,255,0.2); }

.netflix-card-action-btn.primary {
  background: white;
  width: 34px;
  height: 34px;
}

.netflix-card-action-btn.primary:hover { background: rgba(255,255,255,0.85); }
.netflix-card-action-btn svg { width: 14px; height: 14px; }
.netflix-card-action-btn.primary svg { color: var(--bbc-black); width: 16px; height: 16px; }

.netflix-card-detail-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--text-tertiary);
  letter-spacing: 1px;
  text-transform: uppercase;
}

.netflix-card-match {
  color: var(--success);
  font-weight: 700;
}

.netflix-card-detail-desc {
  font-size: 11px;
  color: var(--text-secondary);
  margin-top: 6px;
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* MODAL DETALHES DO CANAL */
.channel-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.88);
  backdrop-filter: blur(12px);
  z-index: 800;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 30px;
  animation: modalFadeIn 0.3s ease;
}

.channel-modal-backdrop.visible { display: flex; }

.channel-modal {
  background: var(--bbc-dark-grey);
  border-radius: 8px;
  max-width: 860px;
  width: 100%;
  max-height: 92vh;
  overflow-y: auto;
  position: relative;
  box-shadow: var(--shadow-xl);
  animation: modalSlideIn 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

.channel-modal-hero {
  position: relative;
  width: 100%;
  height: 380px;
  overflow: hidden;
}

.channel-modal-hero-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  font-weight: 900;
  font-size: 160px;
  letter-spacing: -6px;
  color: rgba(255,255,255,0.06);
  line-height: 0.85;
}

.channel-modal-hero::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 0%, rgba(20,20,20,0.6) 60%, var(--bbc-dark-grey) 100%);
  pointer-events: none;
}

.channel-modal-close {
  position: absolute;
  top: 20px;
  right: 20px;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(0,0,0,0.7);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 10;
  transition: background 0.2s ease;
}

.channel-modal-close:hover { background: var(--bbc-red); }
.channel-modal-close svg { width: 16px; height: 16px; color: white; }

.channel-modal-hero-content {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 40px;
  z-index: 5;
}

.channel-modal-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 10px;
  background: var(--bbc-red);
  color: white;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 14px;
  border-radius: 2px;
}

.channel-modal-eyebrow::before {
  content: '';
  width: 5px;
  height: 5px;
  background: white;
  border-radius: 50%;
  animation: live-pulse 1.3s ease-in-out infinite;
}

.channel-modal-title {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 56px;
  letter-spacing: -2px;
  line-height: 0.95;
  color: white;
  margin-bottom: 12px;
  text-shadow: 0 4px 20px rgba(0,0,0,0.5);
}

.channel-modal-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.channel-modal-actions .hero-btn { padding: 11px 22px; font-size: 12px; }
.channel-modal-actions .hero-btn-secondary {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid rgba(255,255,255,0.5);
  background: transparent;
}

.channel-modal-actions .hero-btn-secondary:hover {
  border-color: white;
  background: rgba(255,255,255,0.1);
}

.channel-modal-actions .hero-btn-secondary svg { width: 18px; height: 18px; }

.channel-modal-body {
  padding: 30px 40px 40px;
}

.channel-modal-meta-row {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.channel-modal-match {
  color: var(--success);
  font-weight: 800;
  font-size: 16px;
  letter-spacing: -0.3px;
}

.channel-modal-rating {
  padding: 2px 8px;
  border: 1px solid var(--border-bright);
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: 1px;
}

.channel-modal-tags-list {
  display: flex;
  gap: 6px;
  margin-left: auto;
  flex-wrap: wrap;
}

.channel-modal-tag {
  padding: 4px 9px;
  background: rgba(255,255,255,0.1);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.5px;
  border-radius: 2px;
}

.channel-modal-description {
  font-family: var(--font-display);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-secondary);
  margin-bottom: 30px;
  letter-spacing: -0.2px;
}

.channel-modal-section {
  margin-bottom: 28px;
}

.channel-modal-section-title {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2.5px;
  color: var(--bbc-red);
  text-transform: uppercase;
  margin-bottom: 14px;
  padding-bottom: 8px;
  border-bottom: 2px solid var(--bbc-red);
  display: inline-block;
}

.channel-modal-info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}

.channel-modal-info-cell {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.channel-modal-info-label {
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 1.5px;
  color: var(--text-tertiary);
  text-transform: uppercase;
}

.channel-modal-info-value {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: -0.2px;
}

.channel-modal-related {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 12px;
}

.channel-modal-related-card {
  background: var(--bbc-near-black);
  border-radius: 4px;
  overflow: hidden;
  cursor: pointer;
  transition: all 0.25s ease;
}

.channel-modal-related-card:hover {
  background: var(--bbc-medium-grey);
  transform: translateY(-3px);
}

.channel-modal-related-thumb {
  position: relative;
  width: 100%;
  padding-bottom: 56.25%;
}

.channel-modal-related-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  font-weight: 900;
  font-size: 24px;
  color: white;
  letter-spacing: -1px;
}

.channel-modal-related-info {
  padding: 10px 12px;
}

.channel-modal-related-name {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: -0.2px;
  margin-bottom: 3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.channel-modal-related-cat {
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--text-tertiary);
  letter-spacing: 1px;
  text-transform: uppercase;
}

/* ONBOARDING MODAL - Estilo Netflix */
.onboarding-backdrop {
  position: fixed;
  inset: 0;
  background: var(--bbc-black);
  z-index: 9700;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 30px;
  animation: modalFadeIn 0.4s ease;
}

.onboarding-backdrop.visible { display: flex; }

.onboarding-content {
  max-width: 720px;
  width: 100%;
  text-align: center;
  animation: modalSlideIn 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

.onboarding-logo {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-bottom: 40px;
}

.onboarding-logo .logo-block { padding: 12px 14px; font-size: 26px; }

.onboarding-title {
  font-family: var(--font-display);
  font-size: 42px;
  font-weight: 800;
  letter-spacing: -1.5px;
  line-height: 1.05;
  margin-bottom: 12px;
}

.onboarding-title em {
  font-style: italic;
  font-weight: 400;
  color: var(--bbc-red);
}

.onboarding-sub {
  font-size: 16px;
  color: var(--text-secondary);
  margin-bottom: 36px;
  font-weight: 500;
}

.onboarding-genres {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 12px;
  margin-bottom: 40px;
}

.onboarding-genre {
  padding: 22px 16px;
  background: var(--bbc-dark-grey);
  border: 2px solid var(--border-medium);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}

.onboarding-genre:hover {
  background: var(--bbc-medium-grey);
  border-color: var(--text-secondary);
}

.onboarding-genre.active {
  background: rgba(187, 25, 25, 0.12);
  border-color: var(--bbc-red);
}

.onboarding-genre-icon {
  font-size: 36px;
  line-height: 1;
}

.onboarding-genre-label {
  font-weight: 700;
  font-size: 13px;
  letter-spacing: -0.2px;
}

.onboarding-genre.active::after {
  content: '✓';
  position: absolute;
  top: 8px;
  right: 8px;
  width: 22px;
  height: 22px;
  background: var(--bbc-red);
  color: white;
  font-size: 13px;
  font-weight: 800;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.onboarding-genre {
  position: relative;
}

.onboarding-actions {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.onboarding-btn {
  padding: 14px 36px;
  font-weight: 800;
  font-size: 14px;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.onboarding-btn-primary {
  background: var(--bbc-red);
  color: white;
  box-shadow: 0 8px 24px var(--shadow-red);
}

.onboarding-btn-primary:hover {
  background: var(--bbc-red-bright);
  transform: translateY(-2px);
}

.onboarding-btn-primary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  background: var(--bbc-pale-grey);
  box-shadow: none;
}

.onboarding-btn-secondary {
  background: transparent;
  color: var(--text-tertiary);
  border: 1px solid var(--border-medium);
}

.onboarding-btn-secondary:hover {
  color: var(--text-primary);
  border-color: var(--text-secondary);
}

/* RESPONSIVE: Mobile */
@media (max-width: 768px) {
  .hero-rotator { padding: 0 14px; margin-bottom: 24px; }
  .hero-stage { height: 320px; border-radius: 4px; }
  .hero-slide-bg { font-size: 100px; letter-spacing: -3px; padding: 30px; }
  .hero-slide-content { padding: 24px; right: 0; }
  .hero-slide-title { font-size: 30px; letter-spacing: -1px; margin-bottom: 10px; }
  .hero-slide-desc { font-size: 13px; margin-bottom: 14px; }
  .hero-btn { padding: 11px 18px; font-size: 11px; }
  .hero-indicators { bottom: 14px; right: 14px; }
  .hero-controls { display: none; }

  .top10-carousel { padding: 16px 14px 24px; gap: 4px; }
  .top10-card { flex: 0 0 160px; height: 150px; padding-left: 50px; }
  .top10-number { font-size: 160px; letter-spacing: -10px; left: -16px; bottom: -22px; -webkit-text-stroke: 2px var(--bbc-red); }
  .top10-thumb { width: 110px; height: 140px; }
  .top10-thumb-bg { font-size: 20px; }
  .top10-card-name { font-size: 11px; }

  .netflix-row { margin-bottom: 32px; }
  .netflix-row-header { padding: 0 14px; }
  .netflix-row-title { font-size: 19px; letter-spacing: -0.4px; }
  .netflix-row-track { padding: 16px 14px; gap: 8px; }
  .netflix-card { flex: 0 0 160px; height: 90px; }
  .netflix-card:hover { transform: none; }
  .netflix-card-detail-popup { display: none; }
  .netflix-card-bg { font-size: 22px; }
  .netflix-card-name { font-size: 11px; }

  .continue-card { flex: 0 0 250px; }
  .continue-thumb-bg { font-size: 32px; }

  .channel-modal-backdrop { padding: 0; }
  .channel-modal { max-width: 100%; max-height: 100vh; border-radius: 0; }
  .channel-modal-hero { height: 280px; }
  .channel-modal-hero-bg { font-size: 90px; letter-spacing: -3px; }
  .channel-modal-hero-content { padding: 20px; }
  .channel-modal-title { font-size: 32px; letter-spacing: -1px; }
  .channel-modal-body { padding: 20px; }
  .channel-modal-info-grid { grid-template-columns: 1fr; gap: 14px; }
  .channel-modal-description { font-size: 14px; }
  .channel-modal-tags-list { margin-left: 0; }
  .channel-modal-related { grid-template-columns: repeat(2, 1fr); gap: 8px; }

  .onboarding-title { font-size: 30px; letter-spacing: -0.8px; }
  .onboarding-sub { font-size: 14px; margin-bottom: 26px; }
  .onboarding-genres { grid-template-columns: repeat(2, 1fr); gap: 10px; }
  .onboarding-genre { padding: 18px 12px; }
  .onboarding-genre-icon { font-size: 28px; }
  .onboarding-genre-label { font-size: 12px; }
  .onboarding-btn { padding: 12px 24px; font-size: 12px; }
}

/* BR TV NEWS V13 - suporte discreto a canais HLS/MP4 sem alterar o visual */
.player-frame video.brtv-hls-video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  background: #000;
  object-fit: contain;
  border: 0;
}


/* V15 - Somente botão de compartilhamento premium WhatsApp: não altera layout, player, imagens ou grade */
.player-action#actionShare,
button#actionShare.player-action {
  background: linear-gradient(135deg, #075e54 0%, #128c7e 42%, #25d366 100%) !important;
  color: #ffffff !important;
  border: 1px solid rgba(37, 211, 102, 0.92) !important;
  box-shadow:
    0 0 0 1px rgba(37, 211, 102, 0.22),
    0 10px 30px rgba(37, 211, 102, 0.18),
    inset 0 1px 0 rgba(255,255,255,0.18) !important;
  position: relative;
  overflow: hidden;
}
.player-action#actionShare::before,
button#actionShare.player-action::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent 0%, rgba(255,255,255,0.22) 50%, transparent 100%);
  transform: translateX(-120%);
  transition: transform 0.55s ease;
  pointer-events: none;
}
.player-action#actionShare:hover,
button#actionShare.player-action:hover {
  background: linear-gradient(135deg, #0a6f63 0%, #15a08f 42%, #2bea73 100%) !important;
  border-color: #6fffa2 !important;
  transform: translateY(-1px);
  box-shadow:
    0 0 0 1px rgba(111, 255, 162, 0.36),
    0 14px 38px rgba(37, 211, 102, 0.28),
    0 0 24px rgba(37, 211, 102, 0.18) !important;
}
.player-action#actionShare:hover::before,
button#actionShare.player-action:hover::before {
  transform: translateX(120%);
}
.player-action#actionShare svg,
button#actionShare.player-action svg {
  filter: drop-shadow(0 0 5px rgba(255,255,255,0.25));
}


/* V17 - tela inicial de preferências removida do fluxo */
.onboarding-backdrop,
#onboardingModal,
.onboarding-backdrop.visible {
  display: none !important;
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
}


/* =========================================================
   BR TV NEWS v18 — CORREÇÃO DO MENU DESKTOP/TABLET
   Preserva o visual original e impede quebra vertical letra por letra.
   ========================================================= */
.header-inner {
  flex-wrap: nowrap !important;
  gap: clamp(10px, 1.35vw, 28px) !important;
}

.logo,
.header-right {
  flex: 0 0 auto !important;
  min-width: max-content !important;
}

.logo-meta {
  white-space: nowrap !important;
  flex: 0 0 auto !important;
}

.main-nav {
  display: flex !important;
  flex: 1 1 auto !important;
  min-width: 0 !important;
  max-width: 100% !important;
  flex-wrap: nowrap !important;
  overflow: hidden !important;
  justify-content: center !important;
}

.nav-item {
  white-space: nowrap !important;
  word-break: normal !important;
  overflow-wrap: normal !important;
  hyphens: none !important;
  flex: 0 0 auto !important;
  min-width: max-content !important;
  line-height: 1.1 !important;
}

.nav-item,
.nav-item * {
  white-space: nowrap !important;
  word-break: normal !important;
  overflow-wrap: normal !important;
}

.search-box {
  flex: 0 1 320px !important;
  width: auto !important;
  min-width: 190px !important;
  max-width: 320px !important;
}

@media (max-width: 1500px) {
  .header-inner { gap: 16px !important; }
  .logo-meta { display: none !important; }
  .nav-item { padding: 10px 12px !important; font-size: 12px !important; }
  .search-box { max-width: 280px !important; min-width: 200px !important; }
}

@media (max-width: 1280px) {
  .header-inner { gap: 12px !important; }
  .nav-item { padding: 9px 9px !important; font-size: 11px !important; }
  .search-box { max-width: 240px !important; min-width: 180px !important; }
}

@media (max-width: 1160px) {
  .main-nav { display: none !important; }
  .search-box { max-width: 320px !important; min-width: 220px !important; }
}

@media (max-width: 768px) {
  .header-inner { flex-wrap: wrap !important; }
  .main-nav { display: none !important; }
  .search-box {
    order: 3 !important;
    width: 100% !important;
    max-width: 100% !important;
    min-width: 0 !important;
    flex: 1 1 100% !important;
  }
}


/* =========================================================
   BRTV V19 - RESGATE MOBILE BLOGGER
   Impede que a versão mobile padrão do Blogger apareça branca.
   ========================================================= */
.mobile .blog-feeds,
.mobile .feed-links,
.mobile #Attribution1,
.mobile .Attribution,
.mobile .post-outer,
.mobile .date-outer,
.mobile .status-msg-wrap {
  display: none !important;
}

@media (max-width: 768px) {
  html, body {
    background: #000 !important;
  }
}


/* BRTV V21 - a seção mobile de resgate nunca aparece no desktop */
.brtv-mobile-gate-section{display:none!important;}
.mobile .brtv-mobile-gate-section{display:block!important;}

head.script:
/**/
(function(){
  try {
    var href = String(window.location.href || '');
    var search = String(window.location.search || '');
    var isBloggerMobile = /(?:\?|&)m=1(?:&|$)/.test(search);
    var rescueLoop = /(?:\?|&)brtv_rescue=1(?:&|$)/.test(search);
    if (isBloggerMobile && !rescueLoop) {
      var url = new URL(window.location.href);
      url.searchParams.set('m', '0');
      url.searchParams.set('brtv_rescue', '1');
      if (!url.hash) url.hash = 'watch';
      window.location.replace(url.toString());
    }
  } catch(e) {}
})();
