body.script:
/**/
(function(){
  function hasParam(name, value){
    try { return new URL(window.location.href).searchParams.get(name) === value; }
    catch(e){ return new RegExp('(?:\\?|&)'+name+'='+value+'(?:&|$)').test(String(window.location.search||'')); }
  }
  function go(){
    try{
      var url = new URL(window.location.href);
      url.searchParams.set('m','0');
      url.searchParams.set('brtv_rescue','1');
      if(!url.hash){ url.hash='watch'; }
      window.location.replace(url.toString());
    }catch(e){
      window.location.href='/?m=0&brtv_rescue=1#watch';
    }
  }
  var isBloggerMobile = hasParam('m','1');
  var alreadyRescued = hasParam('brtv_rescue','1');
  if(isBloggerMobile && !alreadyRescued){
    document.documentElement.classList.add('brtv-force-rescue');
    var btn=document.getElementById('brtv-mobile-rescue-btn');
    if(btn){ btn.addEventListener('click', function(ev){ ev.preventDefault(); go(); }); }
    setTimeout(go, 250);
    setTimeout(function(){ document.documentElement.classList.add('brtv-force-rescue'); }, 800);
  }
})();
