  return name.split(' ').filter(w => w.length > 1).map(w => w[0]).join('').slice(0, 2).toUpperCase();
}

function formatNumber(n) {
  if (n >= 1000000) return (n/1000000).toFixed(1).replace('.', ',') + 'M';
  if (n >= 1000) return (n/1000).toFixed(1).replace('.', ',') + 'K';
  return n.toString();
}

function formatBR(n) {
  return n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min) + min);
}

function getEmbedUrl(channel) {
  if (!channel) return '';
  if (channel.streamUrl) {
    const src = String(channel.streamUrl);
    if (/youtube\.com\/embed\//i.test(src)) return src + (src.indexOf('?') > -1 ? '&' : '?') + 'autoplay=1';
    const watch = src.match(/[?&]v=([^&]+)/);
    const short = src.match(/youtu\.be\/([^?&]+)/);
    if (watch && watch[1]) return 'https://www.youtube.com/embed/' + encodeURIComponent(watch[1]) + '?autoplay=1&rel=0&modestbranding=1';
    if (short && short[1]) return 'https://www.youtube.com/embed/' + encodeURIComponent(short[1]) + '?autoplay=1&rel=0&modestbranding=1';
    if (/(\.m3u8|\.mp4)(\?|#|$)/i.test(src)) return src;
    if (/^https:\/\//i.test(src)) return src;
  }
  if (channel.type === 'live' && channel.channelId) {
    return 'https://www.youtube.com/embed/live_stream?channel=' + channel.channelId + '&autoplay=1';
  }
  if (channel.type === 'video' && channel.videoId) {
    return 'https://www.youtube.com/embed/' + channel.videoId + '?autoplay=1&rel=0&modestbranding=1';
  }
  if (channel.type === 'playlist' && channel.playlistId) {
    return 'https://www.youtube.com/embed/videoseries?list=' + channel.playlistId + '&autoplay=1';
  }
  return '';
}

function findChannelByName(name) {
  for (const country in CHANNELS) {
    const found = CHANNELS[country].find(c => c.name === name);
    if (found) return { ...found, _country: country };
  }
  return null;
}

/* V15 - Link direto + WhatsApp premium sem alterar visual do portal */
function brtvNormalizeText(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ');
}

function getCountryKeyFromParam(value) {
  if (!value) return null;
  const raw = String(value).trim();
  const lower = raw.toLowerCase();
  const upper = raw.toUpperCase();
  if (COUNTRIES[lower]) return lower;
  for (const key in COUNTRIES) {
    if (String(COUNTRIES[key].code || '').toUpperCase() === upper) return key;
    if (brtvNormalizeText(COUNTRIES[key].name) === brtvNormalizeText(raw)) return key;
  }
  return null;
}

function getChannelCountryKey(channel) {
  if (!channel) return STATE.currentCountry || 'br';
  if (channel._country && COUNTRIES[channel._country]) return channel._country;
  for (const key in CHANNELS) {
    const found = (CHANNELS[key] || []).some(c => {
      return c === channel ||
        (c.iptvId && channel.iptvId && c.iptvId === channel.iptvId) ||
        brtvNormalizeText(c.name) === brtvNormalizeText(channel.name);
    });
    if (found) return key;
  }
  return STATE.currentCountry || 'br';
}

function findChannelByDirectId(id, countryHint) {
  if (!id) return null;
  const wanted = brtvNormalizeText(decodeURIComponent(String(id)));
  const countries = [];
  const hinted = getCountryKeyFromParam(countryHint);
  if (hinted) countries.push(hinted);
  Object.keys(CHANNELS).forEach(k => { if (!countries.includes(k)) countries.push(k); });

  for (const key of countries) {
    const list = CHANNELS[key] || [];
    for (const c of list) {
      const candidates = [
        c.iptvId,
        c.id,
        c.channelId,
        c.videoId,
        c.name,
        (c.name ? c.name.replace(/\s+/g, '') : '')
      ].filter(Boolean).map(brtvNormalizeText);

      if (candidates.includes(wanted)) return { ...c, _country: key };
    }
  }
  return null;
}

function getInitialChannelFromUrl() {
  const query = window.location.search || '';
  if (!query || query.indexOf('=') === -1) return null;
  const params = new URLSearchParams(query);
  const countryParam = params.get('pais') || params.get('country');
  const channelParam = params.get('canal') || params.get('channel') || params.get('id');
  const countryKey = getCountryKeyFromParam(countryParam);
  if (countryKey) STATE.currentCountry = countryKey;
  if (!channelParam) return null;
  const found = findChannelByDirectId(channelParam, countryKey || countryParam);
  if (found && found._country) STATE.currentCountry = found._country;
  return found;
}

function getChannelDirectUrl(channel) {
  const ch = channel || STATE.currentChannel;
  if (!ch) return window.location.origin + window.location.pathname + '#watch';
  const countryKey = getChannelCountryKey(ch);
  const country = COUNTRIES[countryKey] || COUNTRIES.br || { code: 'BR' };
  const params = new URLSearchParams();
  params.set('canal', ch.iptvId || ch.id || ch.channelId || ch.videoId || ch.name);
  params.set('pais', country.code || countryKey.toUpperCase());
  params.set('categoria', ch.category || 'general');
  return window.location.origin + window.location.pathname + '?' + params.toString() + '#watch';
}

function openWhatsAppShare(channel) {
  const ch = channel || STATE.currentChannel;
  if (!ch) {
    showToast('Compartilhar', 'Selecione um canal primeiro');
    return;
  }
  const directUrl = getChannelDirectUrl(ch);
  const message =
    '📺 Estou assistindo ' + ch.name + ' ao vivo no BR TV NEWS.' +
    '\n\nToque para abrir direto nesse canal:' +
    '\n' + directUrl;
  const waUrl = 'https://wa.me/?text=' + encodeURIComponent(message);
  try {
    window.open(waUrl, '_blank', 'noopener,noreferrer');
    showToast('WhatsApp', 'Link direto do canal pronto para enviar');
  } catch (e) {
    try {
      navigator.clipboard.writeText(message);
      showToast('Link copiado', 'Cole no WhatsApp para compartilhar');
    } catch (err) {
      window.location.href = waUrl;
    }
  }
}


function initViewers() {
  Object.values(CHANNELS).forEach(list => {
    list.forEach(c => {
      const key = c.name;
      if (!STATE.channelViewers[key]) {
        let base = 8000;
        if (c.featured) base = 145000;
        else if (c.category === 'Notícias') base = randomInt(25000, 85000);
        else base = randomInt(4000, 22000);
        STATE.channelViewers[key] = base;
      }
    });
  });
}

function tickViewers() {
  Object.keys(STATE.channelViewers).forEach(k => {
    const delta = Math.floor(Math.random() * 240 - 120);
    STATE.channelViewers[k] = Math.max(800, STATE.channelViewers[k] + delta);
  });

  const total = Object.values(STATE.channelViewers).reduce((a,b)=>a+b,0);
  const sel = $('statViewers');
  if (sel) sel.textContent = formatNumber(total);

  const fsv = $('footerStatViewers');
  if (fsv) fsv.textContent = formatNumber(total);

  const trend = ((Math.random() * 8) - 2).toFixed(1);
  const trendEl = $('statViewersTrend');
  if (trendEl) {
    trendEl.textContent = (trend > 0 ? '+' : '') + trend + '%';
    trendEl.className = 'editorial-stat-trend ' + (trend >= 0 ? 'up' : 'down');
  }

  if (STATE.currentChannel) {
    const v = STATE.channelViewers[STATE.currentChannel.name];
    const cel = $('currentChannelViewers');
    if (cel && v) cel.textContent = formatNumber(v) + ' assistindo';
    const lbv = $('liveBannerViewers');
    if (lbv && v) lbv.textContent = formatNumber(v) + ' assistindo';
  }
}

function updateClock() {
  const now = new Date();
  const hh = String(now.getHours()).padStart(2, '0');
  const mm = String(now.getMinutes()).padStart(2, '0');
  const ss = String(now.getSeconds()).padStart(2, '0');
  const time = hh + ':' + mm + ':' + ss;
  const c = $('topbarClock');
  if (c) c.textContent = time;
  const p = $('playerLiveTime');
  if (p) p.textContent = time;
}

function updateDate() {
  const now = new Date();
  const dias = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const meses = ['JAN', 'FEV', 'MAR', 'ABR', 'MAI', 'JUN', 'JUL', 'AGO', 'SET', 'OUT', 'NOV', 'DEZ'];
  const txt = dias[now.getDay()] + ' ' + String(now.getDate()).padStart(2,'0') + ' ' + meses[now.getMonth()] + ' ' + now.getFullYear();
  const d = $('topbarDate');
  if (d) d.textContent = txt;
}

function updateHoursOnAir() {
  if (!STATE.bootTime) STATE.bootTime = Date.now();
  const hrs = ((Date.now() - STATE.bootTime) / 3600000).toFixed(0);
  const el = $('statHours');
  if (el) el.textContent = hrs > 0 ? formatNumber(parseInt(hrs)) : '0';
}

function tryGeolocation() {
  const locEl = $('topbarLocation');
  if (!navigator.geolocation || !locEl) {
    if (locEl) locEl.innerHTML = '<span style="color:var(--text-tertiary)">◐</span><span>BR &#183; Brasil</span>';
    return;
  }

  navigator.geolocation.getCurrentPosition(
    pos => {
      const lat = pos.coords.latitude;
      const lng = pos.coords.longitude;
      let cidade = 'BR &#183; Brasil';

      if (lat >= -10 && lat <= -8 && lng >= -37 && lng <= -35) cidade = 'AL &#183; Maceió';
      else if (lat >= -24 && lat <= -23 && lng >= -47 && lng <= -46) cidade = 'SP &#183; São Paulo';
      else if (lat >= -23 && lat <= -22 && lng >= -44 && lng <= -42) cidade = 'RJ &#183; Rio de Janeiro';
      else if (lat >= -16 && lat <= -15 && lng >= -49 && lng <= -47) cidade = 'GO &#183; Goiânia';
      else if (lat >= -13 && lat <= -12 && lng >= -39 && lng <= -38) cidade = 'BA &#183; Salvador';
      else if (lat >= -26 && lat <= -25 && lng >= -50 && lng <= -49) cidade = 'PR &#183; Curitiba';
      else if (lat >= -31 && lat <= -29 && lng >= -52 && lng <= -50) cidade = 'RS &#183; Porto Alegre';
      else if (lat >= -16 && lat <= -15 && lng >= -48 && lng <= -47) cidade = 'DF &#183; Brasília';
      else if (lat >= -20 && lat <= -19 && lng >= -44 && lng <= -43) cidade = 'MG &#183; Belo Horizonte';
      else if (lat >= -4 && lat <= -3 && lng >= -39 && lng <= -38) cidade = 'CE &#183; Fortaleza';
      else if (lat >= -9 && lat <= -7 && lng >= -35 && lng <= -34) cidade = 'PE &#183; Recife';

      locEl.innerHTML = '<span style="color:var(--text-tertiary)">◐</span><span>' + cidade + '</span>';
    },
    () => {
      locEl.innerHTML = '<span style="color:var(--text-tertiary)">◐</span><span>BR</span>';
    },
    { timeout: 4000, maximumAge: 600000 }
  );
}

function fetchRates() {
  fetch('https://economia.awesomeapi.com.br/last/USD-BRL,EUR-BRL,BTC-BRL')
    .then(r => r.json())
    .then(data => {
      if (data.USDBRL) {
        const v = parseFloat(data.USDBRL.bid);
        const ch = parseFloat(data.USDBRL.pctChange);
        updateMarket('usd', 'R$ ' + v.toFixed(2).replace('.', ','), ch);
      }
      if (data.EURBRL) {
        const v = parseFloat(data.EURBRL.bid);
        const ch = parseFloat(data.EURBRL.pctChange);
        updateMarket('eur', 'R$ ' + v.toFixed(2).replace('.', ','), ch);
      }
      if (data.BTCBRL) {
        const v = parseFloat(data.BTCBRL.bid);
        const ch = parseFloat(data.BTCBRL.pctChange);
        updateMarket('btc', 'R$ ' + formatBR(Math.floor(v)), ch);
      }
    })
    .catch(() => {
      ['usd', 'eur', 'btc'].forEach(k => {
        const el = $(k + 'Rate');
        if (el) el.textContent = '--';
      });
    });

  const ibov = (130000 + randomInt(-3000, 3000));
  const ibovCh = ((Math.random() * 4) - 2).toFixed(2);
  updateMarket('ibov', formatBR(ibov) + ' pts', parseFloat(ibovCh));

  const sp = (5800 + randomInt(-100, 100));
  const spCh = ((Math.random() * 3) - 1.5).toFixed(2);
  const spEl = $('market-sp');
  if (spEl) spEl.textContent = formatBR(sp) + ' pts';
  const spChEl = $('market-sp-change');
  if (spChEl) {
    spChEl.textContent = (spCh >= 0 ? '+' : '') + spCh + '%';
    spChEl.className = 'market-change ' + (spCh >= 0 ? 'up' : 'down');
  }
}

function updateMarket(symbol, value, change) {
  const topEl = $(symbol + 'Rate');
  if (topEl) topEl.textContent = value;

  const topChEl = $(symbol + 'Change');
  if (topChEl) {
    const formatted = (change >= 0 ? '+' : '') + change.toFixed(2) + '%';
    topChEl.textContent = formatted;
    topChEl.className = 'top-bar-stock-change ' + (change >= 0 ? 'up' : 'down');
  }

  const marketEl = $('market-' + symbol);
  if (marketEl) marketEl.textContent = value;

  const marketChEl = $('market-' + symbol + '-change');
  if (marketChEl) {
    const formatted = (change >= 0 ? '+' : '') + change.toFixed(2) + '%';
    marketChEl.textContent = formatted;
    marketChEl.className = 'market-change ' + (change >= 0 ? 'up' : 'down');
  }
}
