function buildCountryDropdown() {
  const dd = $('countryDropdown');
  if (!dd) return;

  dd.innerHTML = Object.entries(COUNTRIES).map(([code, c]) => {
    const count = (CHANNELS[code] || []).length;
    return '<div class="country-option ' + (code === STATE.currentCountry ? 'active' : '') + '" data-code="' + code + '">' +
      '<span style="font-size:20px">' + c.flag + '</span>' +
      '<span>' + c.name + '</span>' +
      '<span class="country-count">' + count + '</span>' +
    '</div>';
  }).join('');

  dd.querySelectorAll('.country-option').forEach(opt => {
    opt.addEventListener('click', () => {
      const code = opt.dataset.code;
      STATE.currentCountry = code;
      STATE.currentCategory = 'Todos';
      STATE.channelListCategory = 'Todos';
      updateCountryUI();
      renderAll();
      dd.classList.remove('open');
      $('countryBtn').classList.remove('open');

      const feat = (CHANNELS[code] || []).find(c => c.featured);
      if (feat) {
        setTimeout(() => playChannel(feat, true), 200);
      } else if ((CHANNELS[code] || []).length > 0) {
        playChannel((CHANNELS[code] || [])[0], true);
        showToast('País alterado', COUNTRIES[code].name + ' selecionado');
      } else {
        showToast('Sem canais', COUNTRIES[code].name + ' ainda não tem canais');
      }
    });
  });
}

function updateCountryUI() {
  const c = COUNTRIES[STATE.currentCountry];
  if ($('currentFlag')) $('currentFlag').textContent = c.flag;
  if ($('currentCountry')) $('currentCountry').textContent = c.name;
  if ($('sectionCountryName')) $('sectionCountryName').textContent = c.name;
  if ($('liveBannerEdition')) $('liveBannerEdition').textContent = c.code === 'BR' ? 'NACIONAL' : c.code;

  const n = (CHANNELS[STATE.currentCountry] || []).length;
  if ($('statChannels')) $('statChannels').textContent = n;
  if ($('footerStatChannels')) $('footerStatChannels').textContent = n;
  if ($('channelListCount')) $('channelListCount').textContent = n;
  if ($('listFooterTotal')) $('listFooterTotal').textContent = n;
  if ($('listFooterOnline')) $('listFooterOnline').textContent = n;

  $$('.country-option').forEach(o => o.classList.toggle('active', o.dataset.code === STATE.currentCountry));
}

function bindCountryButton() {
  const btn = $('countryBtn');
  if (!btn) return;
  btn.addEventListener('click', (e) => {
    e.stopPropagation();
    const dd = $('countryDropdown');
    dd.classList.toggle('open');
    btn.classList.toggle('open');
  });
  document.addEventListener('click', (e) => {
    if (!e.target.closest('.country-selector')) {
      $('countryDropdown').classList.remove('open');
      btn.classList.remove('open');
    }
  });
}

function buildEPG() {
  const items = $('epgItems');
  if (!items) return;

  const channels = (CHANNELS[STATE.currentCountry] || []).slice(0, 6);
  if (!channels.length) {
    items.innerHTML = '<div style="color:var(--text-tertiary);font-family:var(--font-mono);font-size:11px">Sem programação disponível</div>';
    return;
  }

  const now = new Date();
  const hh = String(now.getHours()).padStart(2, '0');
  const mm = String(Math.floor(now.getMinutes() / 30) * 30).padStart(2, '0');

  items.innerHTML = channels.map((c, i) => {
    const prog = PROGRAM_NAMES[c.category] || ['Programação ao vivo'];
    const p1 = prog[i % prog.length];
    return '<div class="epg-item" data-name="' + c.name + '">' +
      '<div class="epg-time now">AGORA &#183; ' + hh + ':' + mm + '</div>' +
      '<div class="epg-program">' + p1 + '</div>' +
      '<div class="epg-channel">' + c.name + '</div>' +
    '</div>';
  }).join('');

  items.querySelectorAll('.epg-item').forEach(item => {
    item.addEventListener('click', () => {
      const ch = findChannelByName(item.dataset.name);
      if (ch) playChannel(ch);
    });
  });
}

function buildChannelListCategories() {
  const bar = $('channelListCategories');
  if (!bar) return;

  const channels = CHANNELS[STATE.currentCountry] || [];
  const cats = ['Todos', ...new Set(channels.map(c => c.category))];

  bar.innerHTML = cats.map(cat => {
    return '<button class="list-cat-pill ' + (cat === STATE.channelListCategory ? 'active' : '') + '" data-cat="' + cat + '">' + cat + '</button>';
  }).join('');

  bar.querySelectorAll('.list-cat-pill').forEach(p => {
    p.addEventListener('click', () => {
      STATE.channelListCategory = p.dataset.cat;
      renderChannelList();
      buildChannelListCategories();
    });
  });
}

function getChannelListData() {
  let channels = (CHANNELS[STATE.currentCountry] || []).slice();

  if (STATE.channelListTab === 'trending') {
    channels.sort((a, b) => (STATE.channelViewers[b.name]||0) - (STATE.channelViewers[a.name]||0));
  } else if (STATE.channelListTab === 'favorites') {
    channels = STATE.favorites.map(name => findChannelByName(name)).filter(Boolean).filter(c => c._country === STATE.currentCountry);
  } else if (STATE.channelListTab === 'recent') {
    channels = STATE.history.map(name => findChannelByName(name)).filter(Boolean).filter(c => c._country === STATE.currentCountry);
  }

  if (STATE.channelListCategory !== 'Todos') {
    channels = channels.filter(c => c.category === STATE.channelListCategory);
  }

  if (STATE.channelListSearch) {
    const q = STATE.channelListSearch.toLowerCase();
    channels = channels.filter(c => c.name.toLowerCase().includes(q));
  }

  return channels;
}

function renderChannelList() {
  const body = $('channelListBody');
  if (!body) return;
  const channels = getChannelListData();

  if (!channels.length) {
    let msg = 'Nenhum canal disponível';
    if (STATE.channelListTab === 'favorites') msg = 'Nenhum favorito ainda';
    if (STATE.channelListTab === 'recent') msg = 'Sem histórico recente';

    body.innerHTML = '<div class="list-empty">' +
      '<div class="list-empty-icon">◌</div>' +
      '<div class="list-empty-text">' + msg + '</div>' +
    '</div>';
    return;
  }

  // Agrupar por categoria se for "Todos"
  let html = '';
  if (STATE.channelListCategory === 'Todos' && STATE.channelListTab === 'all') {
    const groups = {};
    channels.forEach(c => {
      if (!groups[c.category]) groups[c.category] = [];
      groups[c.category].push(c);
    });

    Object.keys(groups).forEach(cat => {
      html += '<div class="channel-list-group">';
      html += '<div class="list-group-header">';
      html += '<span class="list-group-title">' + cat + '</span>';
      html += '<span class="list-group-count">' + groups[cat].length + '</span>';
      html += '</div>';
      groups[cat].forEach((c, idx) => {
        html += renderListItem(c, idx + 1);
      });
      html += '</div>';
    });
  } else {
    channels.forEach((c, idx) => {
      html += renderListItem(c, idx + 1);
    });
  }

  body.innerHTML = html;
  bindChannelListItems(body);
}

function renderListItem(c, position) {
  const initials = getInitials(c.name);
  const viewers = STATE.channelViewers[c.name] || 0;
  const isActive = STATE.currentChannel && STATE.currentChannel.name === c.name;
  const isFav = STATE.favorites.includes(c.name);
  const positionStr = String(position).padStart(2, '0');

  return '<div class="list-channel-item ' + (isActive ? 'active' : '') + '" data-name="' + c.name + '">' +
    '<div class="list-channel-thumb" style="background:linear-gradient(135deg, ' + c.color + ' 0%, ' + c.color + 'aa 100%)">' +
      initials +
      '<span class="list-channel-thumb-live">LIVE</span>' +
    '</div>' +
    '<div class="list-channel-meta">' +
      '<div class="list-channel-name">' + c.name + '</div>' +
      '<div class="list-channel-info">' +
        '<span>' + c.category + '</span>' +
        '<span class="list-channel-viewers">' + formatNumber(viewers) + '</span>' +
      '</div>' +
    '</div>' +
    '<div class="list-channel-actions">' +
      '<button class="list-channel-fav ' + (isFav ? 'active' : '') + '" data-fav="' + c.name + '">' +
        '<svg viewBox="0 0 24 24"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>' +
      '</button>' +
      '<span class="list-channel-position">' + positionStr + '</span>' +
    '</div>' +
  '</div>';
}

function bindChannelListItems(container) {
  container.querySelectorAll('.list-channel-item').forEach(item => {
    item.addEventListener('click', (e) => {
      if (e.target.closest('.list-channel-fav')) return;
      const ch = findChannelByName(item.dataset.name);
      if (ch) playChannel(ch);
    });
  });

  container.querySelectorAll('.list-channel-fav').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      toggleFavorite(btn.dataset.fav);
    });
  });
}

function bindChannelListTabs() {
  $$('.list-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      $$('.list-tab').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      STATE.channelListTab = tab.dataset.listTab;
      renderChannelList();
    });
  });
}

function bindChannelListSearch() {
  const input = $('channelListSearch');
  if (!input) return;
  input.addEventListener('input', (e) => {
    STATE.channelListSearch = e.target.value;
    renderChannelList();
  });
}

function buildCategoriesBar() {
  const bar = $('categoriesBar');
  if (!bar) return;
  const channels = CHANNELS[STATE.currentCountry] || [];
  const cats = ['Todos', ...new Set(channels.map(c => c.category))];

  bar.innerHTML = cats.map(cat => {
    const count = cat === 'Todos' ? channels.length : channels.filter(c => c.category === cat).length;
    return '<button class="cat-pill ' + (cat === STATE.currentCategory ? 'active' : '') + '" data-cat="' + cat + '">' +
      '<span>' + cat + '</span>' +
      '<span class="cat-pill-count">' + count + '</span>' +
    '</button>';
  }).join('');

  bar.querySelectorAll('.cat-pill').forEach(p => {
    p.addEventListener('click', () => {
      STATE.currentCategory = p.dataset.cat;
      renderGrid();
      buildCategoriesBar();
    });
  });
}
