function renderChannelCard(c, i) {
  const initials = getInitials(c.name);
  const viewers = STATE.channelViewers[c.name] || 0;
  const isFav = STATE.favorites.includes(c.name);

  return '<div class="channel-card" data-name="' + c.name + '" style="animation-delay:' + (i * 50) + 'ms">' +
    '<div class="channel-thumb">' +
      '<div class="channel-thumb-fallback" style="background:linear-gradient(135deg, ' + c.color + ' 0%, ' + c.color + 'cc 60%, #0a0a0a 100%)">' + initials + '</div>' +
      '<span class="live-tag">AO VIVO</span>' +
      (c.featured ? '<span class="featured-tag">★ DESTAQUE</span>' : '') +
      '<span class="viewers-tag">' + formatNumber(viewers) + '</span>' +
      '<span class="quality-tag">HD 1080P</span>' +
      '<div class="play-overlay"><div class="play-icon"></div></div>' +
    '</div>' +
    '<div class="channel-info">' +
      '<div class="channel-info-top">' +
        '<div class="channel-name">' + c.name + '</div>' +
        '<button class="channel-fav-btn ' + (isFav ? 'active' : '') + '" data-fav="' + c.name + '" title="Favoritar">' +
          '<svg viewBox="0 0 24 24"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>' +
        '</button>' +
      '</div>' +
      '<div class="channel-meta-row">' +
        '<div class="channel-category">' + c.category + '</div>' +
        '<div class="channel-quality">HD</div>' +
      '</div>' +
    '</div>' +
  '</div>';
}

function renderRowCard(c, i) {
  const initials = getInitials(c.name);
  const viewers = STATE.channelViewers[c.name] || 0;
  return '<div class="row-card channel-card" data-name="' + c.name + '" style="animation-delay:' + (i * 50) + 'ms">' +
    '<div class="row-card-thumb">' +
      '<div class="row-card-bg" style="background:linear-gradient(135deg, ' + c.color + ' 0%, ' + c.color + 'cc 60%, #0a0a0a 100%)">' + initials + '</div>' +
      '<span class="live-tag">AO VIVO</span>' +
      '<span class="viewers-tag">' + formatNumber(viewers) + '</span>' +
      '<div class="play-overlay"><div class="play-icon"></div></div>' +
    '</div>' +
    '<div class="row-card-info">' +
      '<div class="row-card-name">' + c.name + '</div>' +
      '<div class="row-card-meta">' +
        '<span class="row-card-cat">' + c.category + '</span>' +
        '<span class="row-card-viewers">' + formatNumber(viewers) + '</span>' +
      '</div>' +
    '</div>' +
  '</div>';
}

function getFilteredChannels() {
  let channels = (CHANNELS[STATE.currentCountry] || []).slice();
  if (STATE.currentCategory !== 'Todos') {
    channels = channels.filter(c => c.category === STATE.currentCategory);
  }
  if (STATE.searchQuery) {
    const q = STATE.searchQuery.toLowerCase();
    channels = channels.filter(c => c.name.toLowerCase().includes(q));
  }
  if (STATE.sortMode === 'az') {
    channels.sort((a, b) => a.name.localeCompare(b.name));
  } else if (STATE.sortMode === 'viewers') {
    channels.sort((a, b) => (STATE.channelViewers[b.name]||0) - (STATE.channelViewers[a.name]||0));
  }
  return channels;
}

function renderGrid() {
  const grid = $('channelsGrid');
  if (!grid) return;
  const channels = getFilteredChannels();

  if (!channels.length) {
    grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:80px 20px;color:var(--text-tertiary)">' +
      '<div style="font-family:var(--font-display);font-size:48px;opacity:0.4;margin-bottom:14px">◌</div>' +
      '<div style="font-family:var(--font-display);font-style:italic;font-size:24px;color:var(--text-secondary);margin-bottom:8px;letter-spacing:-0.5px">Nenhum canal disponível</div>' +
      '<div style="font-family:var(--font-mono);font-size:11px;letter-spacing:2px;text-transform:uppercase">' + COUNTRIES[STATE.currentCountry].name + ' &#183; Em breve</div>' +
    '</div>';
    return;
  }

  grid.innerHTML = channels.map((c, i) => renderChannelCard(c, i)).join('');
  bindCardEvents(grid);
}

function bindCardEvents(container) {
  container.querySelectorAll('.channel-card').forEach(card => {
    card.addEventListener('click', (e) => {
      if (e.target.closest('.channel-fav-btn')) return;
      const name = card.dataset.name;
      const ch = findChannelByName(name);
      if (ch) playChannel(ch);
    });
  });

  container.querySelectorAll('.channel-fav-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      toggleFavorite(btn.dataset.fav);
    });
  });
}

function renderFeaturedRow() {
  const row = $('featuredRow');
  if (!row) return;
  const channels = (CHANNELS[STATE.currentCountry] || []).slice(0, 3);
  if (!channels.length) {
    row.innerHTML = '';
    return;
  }

  const main = channels[0];
  const sides = channels.slice(1, 3);

  let html = '';
  // Main featured
  html += '<div class="featured-card-main channel-card" data-name="' + main.name + '">';
  html += '<div class="featured-card-thumb">';
  html += '<div class="featured-card-bg" style="background:linear-gradient(135deg, ' + main.color + ' 0%, ' + main.color + 'aa 60%, #0a0a0a 100%)">';
  html += getInitials(main.name);
  html += '</div>';
  html += '<div class="featured-card-content">';
  html += '<span class="featured-card-tag">AO VIVO &#183; DESTAQUE</span>';
  html += '<h3 class="featured-card-title">' + main.name + '</h3>';
  html += '<p class="featured-card-sub">' + main.category + ' &#183; ' + formatNumber(STATE.channelViewers[main.name] || 0) + ' assistindo</p>';
  html += '</div>';
  html += '</div>';
  html += '</div>';

  // Side featured
  sides.forEach(c => {
    html += '<div class="featured-card-side channel-card" data-name="' + c.name + '">';
    html += '<div class="featured-card-side-thumb">';
    html += '<div class="featured-card-side-bg" style="background:linear-gradient(135deg, ' + c.color + ' 0%, ' + c.color + 'aa 100%)">';
    html += getInitials(c.name);
    html += '</div>';
    html += '<span class="live-tag" style="top:10px;left:10px">AO VIVO</span>';
    html += '</div>';
    html += '<div class="featured-card-side-content">';
    html += '<div class="featured-card-side-cat">' + c.category + '</div>';
    html += '<div class="featured-card-side-title">' + c.name + '</div>';
    html += '<div class="featured-card-side-meta">';
    html += '<span>' + formatNumber(STATE.channelViewers[c.name] || 0) + ' assistindo</span>';
    html += '<span>&#183;</span>';
    html += '<span>HD</span>';
    html += '</div>';
    html += '</div>';
    html += '</div>';
  });

  row.innerHTML = html;
  bindCardEvents(row);
}

function renderCategoryRow(rowId, category) {
  const row = $(rowId);
  if (!row) return;
  let channels = (CHANNELS[STATE.currentCountry] || []).slice();

  if (category === '_trending') {
    channels.sort((a, b) => (STATE.channelViewers[b.name]||0) - (STATE.channelViewers[a.name]||0));
    channels = channels.slice(0, 10);
  } else {
    channels = channels.filter(c => c.category === category);
  }

  if (!channels.length) {
    row.innerHTML = '<div style="padding:30px;color:var(--text-tertiary);font-family:var(--font-display);font-style:italic;font-size:16px">Sem canais disponíveis nesta categoria</div>';
    return;
  }

  row.innerHTML = channels.map((c, i) => renderRowCard(c, i)).join('');
  bindCardEvents(row);
}

function bindMainSearch() {
  const input = $('channelSearch');
  const results = $('searchResults');
  if (!input || !results) return;

  input.addEventListener('input', (e) => {
    STATE.searchQuery = e.target.value;
    renderGrid();
    renderSearchDropdown();
  });

  input.addEventListener('focus', () => {
    if (STATE.searchQuery) renderSearchDropdown();
  });

  document.addEventListener('click', (e) => {
    if (!e.target.closest('.search-box')) {
      results.classList.remove('visible');
    }
  });
}

function renderSearchDropdown() {
  const results = $('searchResults');
  if (!results) return;
  const q = STATE.searchQuery.toLowerCase();
  if (!q) {
    results.classList.remove('visible');
    return;
  }
  let matches = [];
  Object.keys(CHANNELS).forEach(country => {
    (CHANNELS[country] || []).forEach(c => {
      if (c.name.toLowerCase().includes(q) || c.category.toLowerCase().includes(q)) {
        matches.push({...c, _country: country});
      }
    });
  });
  matches = matches.slice(0, 10);

  if (!matches.length) {
    results.innerHTML = '<div style="padding:30px;text-align:center;color:var(--text-tertiary);font-size:13px;font-style:italic;font-family:var(--font-display);letter-spacing:-0.3px">Nenhum resultado encontrado</div>';
    results.classList.add('visible');
    return;
  }

  let html = '<div class="search-results-header">' + matches.length + ' resultado' + (matches.length > 1 ? 's' : '') + '</div>';
  html += matches.map(c => {
    const init = getInitials(c.name);
    return '<div class="search-result-item" data-name="' + c.name + '" data-country="' + c._country + '">' +
      '<div class="search-result-thumb" style="background:linear-gradient(135deg,' + c.color + ',' + c.color + 'aa)">' + init + '</div>' +
      '<div class="search-result-meta">' +
        '<div class="search-result-name">' + c.name + '</div>' +
        '<div class="search-result-cat">' + c.category + ' &#183; ' + COUNTRIES[c._country].flag + ' ' + COUNTRIES[c._country].name + '</div>' +
      '</div>' +
    '</div>';
  }).join('');
  results.innerHTML = html;
  results.classList.add('visible');

  results.querySelectorAll('.search-result-item').forEach(item => {
    item.addEventListener('click', () => {
      if (item.dataset.country !== STATE.currentCountry) {
        STATE.currentCountry = item.dataset.country;
        updateCountryUI();
        renderAll();
      }
      const ch = findChannelByName(item.dataset.name);
      if (ch) {
        playChannel(ch);
        $('channelSearch').value = '';
        STATE.searchQuery = '';
        results.classList.remove('visible');
        renderGrid();
      }
    });
  });
}
/**/

/**/

function playChannel(channel, autoOpen) {
  if (!channel) return;
  STATE.currentChannel = channel;
  STATE.isPlaying = true;
  const frame = $('playerFrame');
  const embedUrl = getEmbedUrl(channel);
  const rawStream = channel && channel.streamUrl ? String(channel.streamUrl) : '';

  if (rawStream && /(\.m3u8)(\?|#|$)/i.test(rawStream)) {
    frame.innerHTML = '<video id="brtvLiveVideo" class="brtv-hls-video" controls autoplay playsinline webkit-playsinline></video>';
    const video = $('brtvLiveVideo');
    if (video) {
      video.muted = !!STATE.isMuted;
      video.volume = Math.max(0, Math.min(1, (STATE.volume || 70) / 100));
      if (video.canPlayType('application/vnd.apple.mpegurl')) {
        video.src = rawStream;
        video.play().catch(() => {});
      } else if (window.Hls && Hls.isSupported()) {
        try {
          if (STATE.hlsInstance) { STATE.hlsInstance.destroy(); }
          STATE.hlsInstance = new Hls({ lowLatencyMode: true, enableWorker: true });
          STATE.hlsInstance.loadSource(rawStream);
          STATE.hlsInstance.attachMedia(video);
          STATE.hlsInstance.on(Hls.Events.MANIFEST_PARSED, () => video.play().catch(() => {}));
        } catch (err) {
          frame.innerHTML = '<div class="player-placeholder"><div class="player-placeholder-icon">⚠</div><div class="player-placeholder-text">Transmissão indisponível</div><div class="player-placeholder-sub">Tente outro canal</div></div>';
        }
      } else {
        frame.innerHTML = '<div class="player-placeholder"><div class="player-placeholder-icon">⚠</div><div class="player-placeholder-text">HLS não suportado</div><div class="player-placeholder-sub">Atualize o navegador ou tente outro canal</div></div>';
      }
    }
  } else if (rawStream && /(\.mp4)(\?|#|$)/i.test(rawStream)) {
    frame.innerHTML = '<video class="brtv-hls-video" controls autoplay playsinline webkit-playsinline src="' + rawStream + '"></video>';
  } else if (embedUrl) {
    frame.innerHTML = '<iframe id="ytPlayer" src="' + embedUrl + '" allowfullscreen allow="autoplay; encrypted-media; picture-in-picture; fullscreen" frameborder="0"></iframe>';
  } else {
    frame.innerHTML = '<div class="player-placeholder"><div class="player-placeholder-icon">⚠</div><div class="player-placeholder-text">Fonte indisponível</div><div class="player-placeholder-sub">Tente outro canal</div></div>';
  }

  if ($('currentChannelName')) $('currentChannelName').textContent = channel.name;
  if ($('currentChannelDesc')) $('currentChannelDesc').textContent = channel.description || (channel.category + ' · Transmissão ao vivo em alta definição');
  if ($('currentChannelCountry')) $('currentChannelCountry').textContent = COUNTRIES[STATE.currentCountry].name.toUpperCase();
  if ($('liveBannerText')) $('liveBannerText').innerHTML = '<strong>' + channel.name + '</strong> · ' + (channel.description || 'Transmissão ao vivo em alta definição');

  // Histórico e watch time
  STATE.history = [channel.name, ...STATE.history.filter(n => n !== channel.name)].slice(0, 15);
  if (typeof recordWatchStart === 'function') recordWatchStart(channel.name);
  saveState();

  renderChannelList();
  updateFavCurrentButton();
  tickViewers();

  // Re-renderizar seções Netflix-style
  if (typeof renderContinueWatching === 'function') renderContinueWatching();
  if (typeof renderAllNetflixSections === 'function' && STATE.currentView === 'home') {
    // Apenas atualiza "porque você assistiu" sem refazer hero
    const all = CHANNELS[STATE.currentCountry] || [];
    const similar = all.filter(c => c.category === channel.category && c.name !== channel.name);
    const recoSection = $('rowRecoSection');
    const recoTitle = $('rowRecoTitle');
    if (recoSection) recoSection.style.display = similar.length > 0 ? 'block' : 'none';
    if (recoTitle) recoTitle.innerHTML = 'Porque você assistiu <em>' + channel.name + '</em>';
    if (similar.length > 0 && typeof renderNetflixRow === 'function') {
      renderNetflixRow('rowRecoNet', similar, similar.length);
    }
  }

  if (!autoOpen) {
    showToast('Sintonizando', channel.name);
  }
}

function playNextChannel() {
  const list = CHANNELS[STATE.currentCountry] || [];
  if (!list.length) return;
  if (!STATE.currentChannel) { playChannel(list[0]); return; }
  const idx = list.findIndex(c => c.name === STATE.currentChannel.name);
  const next = list[(idx + 1) % list.length];
  playChannel(next);
}

function playPrevChannel() {
  const list = CHANNELS[STATE.currentCountry] || [];
  if (!list.length) return;
  if (!STATE.currentChannel) { playChannel(list[list.length - 1]); return; }
  const idx = list.findIndex(c => c.name === STATE.currentChannel.name);
  const prev = list[(idx - 1 + list.length) % list.length];
  playChannel(prev);
}

function toggleCinemaMode() {
  STATE.isCinemaMode = !STATE.isCinemaMode;
  document.body.classList.toggle('cinema-active', STATE.isCinemaMode);
  showToast(STATE.isCinemaMode ? 'Modo cinema ativado' : 'Modo cinema desativado', 'Pressione C para alternar');
}

function toggleMiniPlayer() {
  if (!STATE.currentChannel) {
    showToast('Sem canal ativo', 'Selecione um canal primeiro');
    return;
  }
  STATE.miniPlayerActive = !STATE.miniPlayerActive;
  const mp = $('miniPlayer');
  const mpFrame = $('miniPlayerFrame');
  const mpName = $('miniPlayerName');

  if (STATE.miniPlayerActive) {
    const embedUrl = getEmbedUrl(STATE.currentChannel);
    mpFrame.innerHTML = '<iframe src="' + embedUrl + '" allowfullscreen allow="autoplay; encrypted-media; picture-in-picture" frameborder="0"></iframe>';
    mpName.textContent = STATE.currentChannel.name;
    mp.classList.add('visible');
    showToast('Mini-player', 'Continue navegando enquanto assiste');
  } else {
    mp.classList.remove('visible');
    setTimeout(() => { mpFrame.innerHTML = ''; }, 400);
  }
}

function toggleFullscreen() {
  const wrapper = $('playerMaster');
  if (!document.fullscreenElement) {
    if (wrapper.requestFullscreen) wrapper.requestFullscreen();
    else if (wrapper.webkitRequestFullscreen) wrapper.webkitRequestFullscreen();
    STATE.isFullscreen = true;
  } else {
    if (document.exitFullscreen) document.exitFullscreen();
    else if (document.webkitExitFullscreen) document.webkitExitFullscreen();
    STATE.isFullscreen = false;
  }
}

function togglePlayPause() {
  if (!STATE.currentChannel) {
    showToast('Sem canal', 'Selecione um canal primeiro');
    return;
  }
  STATE.isPlaying = !STATE.isPlaying;
  const iframe = document.querySelector('#playerFrame iframe');
  if (iframe) {
    const src = iframe.src;
    if (STATE.isPlaying) {
      iframe.src = src;
    } else {
      iframe.src = '';
    }
  }
  const playBtn = $('btnPlay');
  if (playBtn) {
    playBtn.innerHTML = STATE.isPlaying
      ? '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>'
      : '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>';
  }
}

function toggleMute() {
  STATE.isMuted = !STATE.isMuted;
  const fill = $('volFill');
  const handle = $('volHandle');
  if (STATE.isMuted) {
    if (fill) fill.style.width = '0%';
    if (handle) handle.style.left = '0%';
  } else {
    if (fill) fill.style.width = STATE.volume + '%';
    if (handle) handle.style.left = STATE.volume + '%';
  }
  showToast(STATE.isMuted ? 'Mudo ativado' : 'Som restaurado', 'Volume ' + (STATE.isMuted ? 'desabilitado' : STATE.volume + '%'));
}

function setVolume(percent) {
  STATE.volume = Math.max(0, Math.min(100, percent));
  STATE.isMuted = false;
  const fill = $('volFill');
  const handle = $('volHandle');
  if (fill) fill.style.width = STATE.volume + '%';
  if (handle) handle.style.left = STATE.volume + '%';
}

function bindVolumeSlider() {
  const slider = $('volSlider');
  if (!slider) return;
  let dragging = false;

  function calcVolume(e) {
    const rect = slider.getBoundingClientRect();
    const x = (e.clientX || (e.touches && e.touches[0].clientX) || 0) - rect.left;
    const percent = Math.round((x / rect.width) * 100);
    setVolume(percent);
  }

  slider.addEventListener('mousedown', (e) => {
    dragging = true;
    calcVolume(e);
  });
  document.addEventListener('mousemove', (e) => { if (dragging) calcVolume(e); });
  document.addEventListener('mouseup', () => { dragging = false; });
}

function toggleFavorite(name) {
  const idx = STATE.favorites.indexOf(name);
  if (idx >= 0) {
    STATE.favorites.splice(idx, 1);
    showToast('Removido', name + ' fora dos favoritos');
  } else {
    STATE.favorites.push(name);
    showToast('Favoritado', name + ' adicionado aos favoritos');
  }
  saveState();
  renderGrid();
  renderChannelList();
  renderFavoritesView();
  renderFeaturedRow();
  renderHistoryView();
  updateFavBadge();
  updateFavCurrentButton();
}

function updateFavBadge() {
  const badge = $('favBadge');
  const navBadge = $('navFavBadge');
  const count = STATE.favorites.length;

  if (badge) {
    if (count > 0) {
      badge.style.display = 'block';
      badge.textContent = count;
    } else {
      badge.style.display = 'none';
    }
  }

  if (navBadge) {
    if (count > 0) {
      navBadge.style.display = 'inline-block';
      navBadge.textContent = count;
    } else {
      navBadge.style.display = 'none';
    }
  }
}

function updateFavCurrentButton() {
  const btn = $('btnFavCurrent');
  if (!btn || !STATE.currentChannel) return;
  if (STATE.favorites.includes(STATE.currentChannel.name)) {
    btn.classList.add('active');
    btn.querySelector('svg').setAttribute('fill', 'currentColor');
    btn.style.color = 'white';
    btn.style.background = 'var(--bbc-red)';
  } else {
    btn.classList.remove('active');
    btn.querySelector('svg').setAttribute('fill', 'none');
    btn.style.color = '';
    btn.style.background = '';
  }
}

function renderFavoritesView() {
  const grid = $('favoritesGrid');
  if (!grid) return;
  const channels = STATE.favorites.map(name => findChannelByName(name)).filter(Boolean);
  if (!channels.length) {
    grid.innerHTML = '<div class="no-favorites" style="grid-column:1/-1">' +
      '<div class="no-favorites-icon">♡</div>' +
      '<div class="no-favorites-title">Nenhum favorito ainda</div>' +
      '<div class="no-favorites-sub">Marque canais com a estrela para vê-los aqui</div>' +
    '</div>';
    return;
  }
  grid.innerHTML = channels.map((c, i) => renderChannelCard(c, i)).join('');
  bindCardEvents(grid);
}

function renderHistoryView() {
  const grid = $('historyGrid');
  if (!grid) return;
  const channels = STATE.history.map(name => findChannelByName(name)).filter(Boolean);
  if (!channels.length) {
    grid.innerHTML = '<div class="no-favorites" style="grid-column:1/-1">' +
      '<div class="no-favorites-icon">◷</div>' +
      '<div class="no-favorites-title">Sem histórico</div>' +
      '<div class="no-favorites-sub">Os canais que você assistir aparecerão aqui</div>' +
    '</div>';
    return;
  }
  grid.innerHTML = channels.map((c, i) => renderChannelCard(c, i)).join('');
  bindCardEvents(grid);
}

function switchView(view) {
  const validViews = ['home', 'all', 'favorites', 'history', 'news', 'sports', 'entertainment'];
  if (!validViews.includes(view)) view = 'home';

  STATE.currentView = view;

  $('viewHome').style.display = (view === 'home' || view === 'all' || view === 'news' || view === 'sports' || view === 'entertainment') ? 'block' : 'none';

  const fav = $('viewFavorites');
  const hist = $('viewHistory');
  if (fav) fav.classList.toggle('active', view === 'favorites');
  if (hist) hist.classList.toggle('active', view === 'history');

  if (view === 'favorites') renderFavoritesView();
  if (view === 'history') renderHistoryView();

  if (view === 'all') {
    STATE.currentCategory = 'Todos';
    STATE.searchQuery = '';
    $('channelSearch').value = '';
    renderAll();
    setTimeout(() => {
      const section = $('channelsSection');
      if (section) section.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  } else if (view === 'news') {
    STATE.currentCategory = 'Notícias';
    renderGrid();
    buildCategoriesBar();
    setTimeout(() => {
      const section = $('channelsSection');
      if (section) section.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  } else if (view === 'sports') {
    STATE.currentCategory = 'Esportes';
    renderGrid();
    buildCategoriesBar();
    setTimeout(() => {
      const section = $('channelsSection');
      if (section) section.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  } else if (view === 'entertainment') {
    STATE.currentCategory = 'Variedades';
    renderGrid();
    buildCategoriesBar();
    setTimeout(() => {
      const section = $('channelsSection');
      if (section) section.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  } else if (view === 'home') {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  $$('.nav-item').forEach(n => n.classList.toggle('active', n.dataset.view === view));
  $$('.mobile-nav-item').forEach(n => {
    if (n.dataset.view) {
      n.classList.toggle('active', n.dataset.view === view);
    }
  });
}

function bindNavigation() {
  $$('.nav-item').forEach(n => {
    n.addEventListener('click', () => {
      if (n.dataset.view) switchView(n.dataset.view);
    });
  });

  $$('.mobile-nav-item').forEach(n => {
    n.addEventListener('click', () => {
      if (n.dataset.action === 'search') {
        $('channelSearch').focus();
        $('channelSearch').scrollIntoView({ behavior: 'smooth', block: 'center' });
      } else if (n.dataset.action === 'country') {
        $('countryDropdown').classList.toggle('open');
      } else if (n.dataset.view) {
        switchView(n.dataset.view);
      }
    });
  });

  $$('.row-section-more').forEach(btn => {
    btn.addEventListener('click', () => {
      const cat = btn.dataset.cat;
      if (cat === '_trending') {
        STATE.currentCategory = 'Todos';
        STATE.sortMode = 'viewers';
      } else {
        STATE.currentCategory = cat;
      }
      renderGrid();
      buildCategoriesBar();
      setTimeout(() => {
        const section = $('channelsSection');
        if (section) section.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    });
  });
}
