function showToast(title, msg) {
  const container = $('toastContainer');
  if (!container) return;
  const toast = document.createElement('div');
  toast.className = 'toast';
  toast.innerHTML = '<div class="toast-icon"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/></svg></div>' +
    '<div class="toast-content">' +
      '<div class="toast-title">' + title + '</div>' +
      '<div class="toast-msg">' + msg + '</div>' +
    '</div>';
  container.appendChild(toast);
  setTimeout(() => {
    toast.classList.add('exit');
    setTimeout(() => toast.remove(), 300);
  }, 2800);
}

function addFakeComment() {
  const container = $('liveComments');
  if (!container) return;
  const commenter = FAKE_COMMENTERS[randomInt(0, FAKE_COMMENTERS.length)];
  const text = FAKE_COMMENT_TEXTS[randomInt(0, FAKE_COMMENT_TEXTS.length)];
  const time = randomInt(1, 60) + 'min';
  const initials = getInitials2(commenter.name);

  const comment = document.createElement('div');
  comment.className = 'comment-row';
  comment.innerHTML = '<div class="comment-avatar" style="background:' + commenter.color + '">' + initials + '</div>' +
    '<div class="comment-body">' +
      '<div class="comment-meta">' +
        '<span class="comment-name">' + commenter.name + '</span>' +
        '<span class="comment-time">há ' + time + '</span>' +
      '</div>' +
      '<div class="comment-text">' + text + '</div>' +
    '</div>';

  container.insertBefore(comment, container.firstChild);

  // Mantém max 8 comentários
  while (container.children.length > 8) {
    container.removeChild(container.lastChild);
  }

  const countEl = $('liveCommentsCount');
  if (countEl) {
    const total = randomInt(180, 480);
    countEl.textContent = total + ' ativos';
  }
}

function initFakeComments() {
  // Adiciona 5 comentários iniciais
  for (let i = 0; i < 5; i++) {
    addFakeComment();
  }
  // Continua adicionando periodicamente
  setInterval(() => {
    if (Math.random() > 0.3) addFakeComment();
  }, randomInt(4000, 7000));
}

function saveState() {
  try {
    const data = {
      favorites: STATE.favorites,
      history: STATE.history,
      currentCountry: STATE.currentCountry,
      volume: STATE.volume
    };
    sessionStorage.setItem('brtvnews_state', JSON.stringify(data));
  } catch (e) {}
}

function loadState() {
  try {
    const raw = sessionStorage.getItem('brtvnews_state');
    if (!raw) return;
    const data = JSON.parse(raw);
    if (data.favorites) STATE.favorites = data.favorites;
    if (data.history) STATE.history = data.history;
    if (data.currentCountry && COUNTRIES[data.currentCountry]) STATE.currentCountry = data.currentCountry;
    if (typeof data.volume === 'number') STATE.volume = data.volume;
  } catch (e) {}
}

function bindKeyboard() {
  document.addEventListener('keydown', (e) => {
    // Não interfere quando digita em inputs
    if (e.target.matches('input, textarea')) return;

    if (e.key === 'ArrowRight' || e.key === 'n' || e.key === 'N') {
      playNextChannel();
    } else if (e.key === 'ArrowLeft' || e.key === 'p' || e.key === 'P') {
      playPrevChannel();
    } else if (e.key === 'c' || e.key === 'C') {
      toggleCinemaMode();
    } else if (e.key === 'f' || e.key === 'F') {
      toggleFullscreen();
    } else if (e.key === 'm' || e.key === 'M') {
      toggleMute();
    } else if (e.key === ' ') {
      e.preventDefault();
      togglePlayPause();
    } else if (e.key === 'Escape') {
      if (STATE.isCinemaMode) toggleCinemaMode();
      if (STATE.miniPlayerActive) toggleMiniPlayer();
      $('countryDropdown').classList.remove('open');
      $('countryBtn').classList.remove('open');
      $('searchResults').classList.remove('visible');
    } else if (e.key === '/') {
      e.preventDefault();
      $('channelSearch').focus();
    }
  });
}

function bindPullRefresh() {
  let startY = 0;
  let pullDistance = 0;
  let isPulling = false;

  const indicator = document.createElement('div');
  indicator.className = 'pull-refresh';
  indicator.innerHTML = '<div class="pull-refresh-spinner"></div><span>ATUALIZANDO...</span>';
  document.body.appendChild(indicator);

  document.addEventListener('touchstart', (e) => {
    if (window.scrollY === 0) {
      startY = e.touches[0].clientY;
      isPulling = true;
    }
  }, { passive: true });

  document.addEventListener('touchmove', (e) => {
    if (!isPulling) return;
    pullDistance = e.touches[0].clientY - startY;
    if (pullDistance > 80) {
      indicator.classList.add('active');
    }
  }, { passive: true });

  document.addEventListener('touchend', () => {
    if (pullDistance > 80) {
      setTimeout(() => {
        renderAll();
        tickViewers();
        fetchRates();
        indicator.classList.remove('active');
        showToast('Atualizado', 'Conteúdo recarregado');
      }, 800);
    } else {
      indicator.classList.remove('active');
    }
    isPulling = false;
    pullDistance = 0;
  });
}

function bindSwipeGestures() {
  const player = $('playerMaster');
  if (!player) return;
  let startX = 0;
  let endX = 0;

  player.addEventListener('touchstart', (e) => {
    startX = e.touches[0].clientX;
  }, { passive: true });

  player.addEventListener('touchend', (e) => {
    endX = e.changedTouches[0].clientX;
    const delta = endX - startX;
    if (Math.abs(delta) > 80) {
      if (delta > 0) playPrevChannel();
      else playNextChannel();
    }
  });
}

function updateListFooterTime() {
  const update = $('listFooterUpdate');
  if (update) {
    const now = new Date();
    const hh = String(now.getHours()).padStart(2, '0');
    const mm = String(now.getMinutes()).padStart(2, '0');
    update.textContent = 'UPDATED ' + hh + ':' + mm;
  }
}

function updateEditorialTime() {
  const el = $('editorialTime');
  if (el) {
    const min = randomInt(1, 4);
    el.textContent = 'ATUALIZADO HÁ ' + min + ' MIN';
  }
}
/**/

/**/

// ===== PWA INSTALLATION MANAGER =====

const PWA = {
  deferredPrompt: null,
  isStandalone: false,
  isIOS: false,
  isAndroid: false,
  hasPromptedThisSession: false,
  dismissedKey: 'brtvnews_install_dismissed',
  installedKey: 'brtvnews_pwa_installed'
};

function detectPlatform() {
  const ua = navigator.userAgent.toLowerCase();
  PWA.isIOS = /iphone|ipad|ipod/.test(ua) && !window.MSStream;
  PWA.isAndroid = /android/.test(ua);

  PWA.isStandalone = window.matchMedia('(display-mode: standalone)').matches ||
                     window.matchMedia('(display-mode: minimal-ui)').matches ||
                     window.navigator.standalone === true ||
                     document.referrer.includes('android-app://');
}

function isInstallDismissed() {
  try {
    const ts = parseInt(localStorage.getItem(PWA.dismissedKey) || '0', 10);
    if (!ts) return false;
    // Mostra de novo após 3 dias
    return (Date.now() - ts) < (3 * 24 * 60 * 60 * 1000);
  } catch (e) {
    return false;
  }
}

function markInstallDismissed() {
  try { localStorage.setItem(PWA.dismissedKey, String(Date.now())); } catch (e) {}
}

function markInstalled() {
  try { localStorage.setItem(PWA.installedKey, '1'); } catch (e) {}
}

function wasInstalled() {
  try { return localStorage.getItem(PWA.installedKey) === '1'; } catch (e) { return false; }
}

function showInstallBanner() {
  if (PWA.isStandalone || isInstallDismissed()) return;
  const banner = $('installBanner');
  if (!banner) return;
  banner.classList.add('visible');
  document.body.classList.add('install-banner-visible');

  const headerBtn = $('headerInstallBtn');
  if (headerBtn) headerBtn.classList.add('visible');
}

function hideInstallBanner() {
  const banner = $('installBanner');
  if (banner) banner.classList.remove('visible');
  document.body.classList.remove('install-banner-visible');
}

function showInstallModal() {
  if (PWA.isStandalone) return;
  const modal = $('installModal');
  if (!modal) return;

  // Mostrar instruções específicas
  const androidInstr = $('installInstructionsAndroid');
  const iosInstr = $('installInstructionsIos');
  const cta = $('installModalCta');

  if (PWA.isIOS) {
    if (iosInstr) iosInstr.style.display = 'block';
    if (androidInstr) androidInstr.style.display = 'none';
    if (cta) cta.style.display = 'none';
  } else if (PWA.deferredPrompt) {
    if (androidInstr) androidInstr.style.display = 'none';
    if (iosInstr) iosInstr.style.display = 'none';
    if (cta) cta.style.display = 'flex';
  } else {
    if (androidInstr) androidInstr.style.display = 'block';
    if (iosInstr) iosInstr.style.display = 'none';
    if (cta) cta.style.display = 'none';
  }

  modal.classList.add('visible');
  PWA.hasPromptedThisSession = true;
}

function hideInstallModal() {
  const modal = $('installModal');
  if (modal) modal.classList.remove('visible');
}

async function triggerInstall() {
  if (!PWA.deferredPrompt) {
    showInstallModal();
    return;
  }

  try {
    PWA.deferredPrompt.prompt();
    const { outcome } = await PWA.deferredPrompt.userChoice;
    if (outcome === 'accepted') {
      markInstalled();
      hideInstallBanner();
      hideInstallModal();
      showToast('App instalado', 'BR TV NEWS adicionado à tela inicial');
    } else {
      markInstallDismissed();
    }
    PWA.deferredPrompt = null;
  } catch (e) {
    showInstallModal();
  }
}

function bindInstallUI() {
  const banner = $('installBanner');
  const bannerBtn = $('installBannerBtn');
  const bannerClose = $('installBannerClose');
  const modalCta = $('installModalCta');
  const modalSecondary = $('installModalSecondary');
  const modalClose = $('installModalClose');
  const modal = $('installModal');
  const headerBtn = $('headerInstallBtn');

  if (bannerBtn) {
    bannerBtn.addEventListener('click', () => {
      if (PWA.deferredPrompt) {
        triggerInstall();
      } else {
        showInstallModal();
      }
    });
  }

  if (bannerClose) {
    bannerClose.addEventListener('click', () => {
      hideInstallBanner();
      markInstallDismissed();
    });
  }

  if (headerBtn) {
    headerBtn.addEventListener('click', () => {
      if (PWA.deferredPrompt) {
        triggerInstall();
      } else {
        showInstallModal();
      }
    });
  }

  if (modalCta) modalCta.addEventListener('click', triggerInstall);

  if (modalSecondary) {
    modalSecondary.addEventListener('click', () => {
      hideInstallModal();
      markInstallDismissed();
    });
  }

  if (modalClose) {
    modalClose.addEventListener('click', () => {
      hideInstallModal();
    });
  }

  if (modal) {
    modal.addEventListener('click', (e) => {
      if (e.target === modal) hideInstallModal();
    });
  }
}

function setupPWAListeners() {
  // Chrome / Edge / Samsung Internet (Android)
  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    PWA.deferredPrompt = e;
    showInstallBanner();
  });

  // Confirmação de instalação
  window.addEventListener('appinstalled', () => {
    markInstalled();
    hideInstallBanner();
    hideInstallModal();
    PWA.deferredPrompt = null;
    PWA.isStandalone = true;
    showToast('App instalado!', 'Acesse pela tela inicial do dispositivo');
  });
}

function initPWA() {
  detectPlatform();
  bindInstallUI();
  setupPWAListeners();

  // Se já está rodando como app, não mostra nada
  if (PWA.isStandalone) {
    return;
  }

  // Para iOS, o beforeinstallprompt não dispara — mostra banner direto após delay
  if (PWA.isIOS && !isInstallDismissed()) {
    setTimeout(() => showInstallBanner(), 5000);
  }

  // Mostra modal automático apenas na primeira visita, após 8s
  if (!isInstallDismissed() && !wasInstalled()) {
    setTimeout(() => {
      if (!PWA.isStandalone && !PWA.hasPromptedThisSession) {
        // Só auto-mostra em mobile
        if (window.innerWidth <= 1024) {
          showInstallModal();
        }
      }
    }, 8000);
  }

  // Sempre mostra botão de instalar no header (para Android quando prompt vier)
  // Para iOS mostra direto pois não tem prompt nativo
  if (PWA.isIOS) {
    const headerBtn = $('headerInstallBtn');
    if (headerBtn) headerBtn.classList.add('visible');
  }
}

// Service Worker via Blob URL (funciona em Blogger sem precisar de arquivo separado)
function registerServiceWorker() {
  if (!('serviceWorker' in navigator)) return;

  const swCode = `
    const CACHE = 'brtv-cache-v1';
    const CORE_ASSETS = ['/', '/index.html'];

    self.addEventListener('install', e => {
      self.skipWaiting();
    });

    self.addEventListener('activate', e => {
      e.waitUntil(
        caches.keys().then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k))))
      );
      self.clients.claim();
    });

    self.addEventListener('fetch', e => {
      const req = e.request;
      if (req.method !== 'GET') return;
      const url = new URL(req.url);
      if (url.origin !== location.origin) return;

      e.respondWith(
        caches.match(req).then(cached => {
          const fetchPromise = fetch(req).then(resp => {
            if (resp && resp.status === 200 && resp.type === 'basic') {
              const copy = resp.clone();
              caches.open(CACHE).then(cache => cache.put(req, copy));
            }
            return resp;
          }).catch(() => cached || new Response('Offline', { status: 503 }));
          return cached || fetchPromise;
        })
      );
    });
  `;

  try {
    const blob = new Blob([swCode], { type: 'application/javascript' });
    const swUrl = URL.createObjectURL(blob);
    // Tenta registrar — pode falhar no Blogger por causa de scope, mas o app funciona normalmente
    navigator.serviceWorker.register(swUrl).catch(() => {
      // SW exige arquivo no mesmo origin/scope. Blogger não permite.
      // O PWA ainda funciona via manifest+meta tags para instalação.
    });
  } catch (e) {}
}

