// ===== HERO ROTATOR (Netflix-style) =====
function renderHeroRotator() {
  const stage = $('heroStage');
  const indicators = $('heroIndicators');
  if (!stage) return;

  const channels = (CHANNELS[STATE.currentCountry] || []).filter(c => c.hero);
  if (!channels.length) {
    stage.innerHTML = '';
    if (indicators) indicators.innerHTML = '';
    return;
  }

  stage.innerHTML = channels.map((c, i) => {
    const initials = getInitials(c.name);
    const matchScore = randomInt(82, 98);
    return '<div class="hero-slide ' + (i === STATE.heroIndex ? 'active' : '') + '" data-idx="' + i + '" data-name="' + c.name + '">' +
      '<div class="hero-slide-bg" style="--hero-color:' + c.color + '">' + initials + '</div>' +
      '<div class="hero-slide-content">' +
        '<span class="hero-slide-eyebrow">AO VIVO &#183; ' + c.category + '</span>' +
        '<h1 class="hero-slide-title">' + c.name + '</h1>' +
        '<p class="hero-slide-desc">' + (c.description || '').substring(0, 220) + '</p>' +
        '<div class="hero-slide-meta">' +
          '<span class="hero-slide-meta-tag match">' + matchScore + '% Match</span>' +
          '<span class="hero-slide-meta-tag rating">' + (c.rating || 'L') + '</span>' +
          '<span class="hero-slide-meta-tag">' + (c.quality || 'HD') + '</span>' +
          (c.tags || []).slice(0, 2).map(t => '<span class="hero-slide-meta-tag">' + t + '</span>').join('') +
        '</div>' +
        '<div class="hero-slide-buttons">' +
          '<button class="hero-btn hero-btn-primary" data-action="play">' +
            '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>' +
            'Assistir agora' +
          '</button>' +
          '<button class="hero-btn hero-btn-secondary" data-action="details">' +
            '<svg viewBox="0 0 24 24" fill="currentColor" style="width:14px;height:14px"><path d="M11 7h2v2h-2zm0 4h2v6h-2zm1-9C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8z"/></svg>' +
            'Mais informações' +
          '</button>' +
        '</div>' +
      '</div>' +
    '</div>';
  }).join('');

  if (indicators) {
    indicators.innerHTML = channels.map((c, i) => {
      return '<div class="hero-indicator ' + (i === STATE.heroIndex ? 'active' : '') + '" data-idx="' + i + '"></div>';
    }).join('');

    indicators.querySelectorAll('.hero-indicator').forEach(ind => {
      ind.addEventListener('click', () => {
        STATE.heroIndex = parseInt(ind.dataset.idx, 10);
        renderHeroRotator();
        resetHeroTimer();
      });
    });
  }

  stage.querySelectorAll('.hero-slide').forEach(slide => {
    slide.querySelectorAll('[data-action="play"]').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const ch = findChannelByName(slide.dataset.name);
        if (ch) playChannel(ch);
      });
    });
    slide.querySelectorAll('[data-action="details"]').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        openChannelModal(slide.dataset.name);
      });
    });
  });
}

function nextHero() {
  const channels = (CHANNELS[STATE.currentCountry] || []).filter(c => c.hero);
  if (!channels.length) return;
  STATE.heroIndex = (STATE.heroIndex + 1) % channels.length;
  renderHeroRotator();
}

function prevHero() {
  const channels = (CHANNELS[STATE.currentCountry] || []).filter(c => c.hero);
  if (!channels.length) return;
  STATE.heroIndex = (STATE.heroIndex - 1 + channels.length) % channels.length;
  renderHeroRotator();
}

function resetHeroTimer() {
  if (STATE.heroTimer) clearInterval(STATE.heroTimer);
  STATE.heroTimer = setInterval(nextHero, 7000);
}

function bindHeroControls() {
  const prev = $('heroPrev');
  const next = $('heroNext');
  if (prev) prev.addEventListener('click', () => { prevHero(); resetHeroTimer(); });
  if (next) next.addEventListener('click', () => { nextHero(); resetHeroTimer(); });
}

// ===== TOP 10 SECTION =====
function renderTop10() {
  const carousel = $('top10Carousel');
  if (!carousel) return;
  let channels = (CHANNELS[STATE.currentCountry] || []).slice();
  channels.sort((a, b) => (STATE.channelViewers[b.name] || 0) - (STATE.channelViewers[a.name] || 0));
  channels = channels.slice(0, 10);

  carousel.innerHTML = channels.map((c, i) => {
    const initials = getInitials(c.name);
    const trending = i < 3 ? '<span class="top10-tag">TOP ' + (i+1) + '</span>' : '';
    return '<div class="top10-card" data-name="' + c.name + '">' +
      '<div class="top10-number">' + (i+1) + '</div>' +
      '<div class="top10-thumb">' +
        '<div class="top10-thumb-bg" style="background:linear-gradient(135deg,' + c.color + ' 0%, ' + c.color + 'aa 60%, #0a0a0a 100%)">' + initials + '</div>' +
        trending +
        '<div class="top10-card-overlay">' +
          '<div class="top10-card-name">' + c.name + '</div>' +
          '<div class="top10-card-cat">' + c.category + ' &#183; ' + formatNumber(STATE.channelViewers[c.name]||0) + '</div>' +
        '</div>' +
      '</div>' +
    '</div>';
  }).join('');

  carousel.querySelectorAll('.top10-card').forEach(card => {
    card.addEventListener('click', () => {
      const ch = findChannelByName(card.dataset.name);
      if (ch) playChannel(ch);
    });
  });
}

// ===== NETFLIX-STYLE ROW (hover expand) =====
function renderNetflixRow(rowId, channels, count) {
  const track = $(rowId);
  if (!track) return;

  const counter = $(rowId + 'Count');
  if (counter && typeof count === 'number') counter.textContent = '(' + count + ' canais)';

  if (!channels.length) {
    track.innerHTML = '<div style="padding:30px;color:var(--text-tertiary);font-family:var(--font-display);font-style:italic;font-size:14px">Sem canais disponíveis</div>';
    return;
  }

  track.innerHTML = channels.map((c, i) => {
    const initials = getInitials(c.name);
    const isFav = STATE.favorites.includes(c.name);
    const isMyList = STATE.myList.includes(c.name);
    const matchScore = randomInt(82, 97);

    return '<div class="netflix-card" data-name="' + c.name + '">' +
      '<div class="netflix-card-inner">' +
        '<div class="netflix-card-bg" style="background:linear-gradient(135deg,' + c.color + ' 0%, ' + c.color + 'cc 60%, #0a0a0a 100%)">' + initials + '</div>' +
        '<span class="netflix-card-live-tag">LIVE</span>' +
        '<div class="netflix-card-bottom">' +
          '<div class="netflix-card-name">' + c.name + '</div>' +
          '<div class="netflix-card-meta-row">' +
            '<span>' + c.category + '</span>' +
            '<span>&#183;</span>' +
            '<span>' + formatNumber(STATE.channelViewers[c.name]||0) + '</span>' +
          '</div>' +
        '</div>' +
      '</div>' +
      '<div class="netflix-card-detail-popup">' +
        '<div class="netflix-card-detail-actions">' +
          '<button class="netflix-card-action-btn primary" data-act="play" title="Assistir">' +
            '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>' +
          '</button>' +
          '<button class="netflix-card-action-btn" data-act="mylist" title="Minha Lista">' +
            '<svg viewBox="0 0 24 24" fill="' + (isMyList ? 'var(--bbc-red)' : 'none') + '" stroke="currentColor" stroke-width="2"><path d="M' + (isMyList ? '20 6L9 17l-5-5' : '12 4v16m-8-8h16') + '"/></svg>' +
          '</button>' +
          '<button class="netflix-card-action-btn" data-act="fav" title="Favoritar">' +
            '<svg viewBox="0 0 24 24" fill="' + (isFav ? 'var(--bbc-red)' : 'none') + '" stroke="' + (isFav ? 'var(--bbc-red)' : 'currentColor') + '" stroke-width="2"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>' +
          '</button>' +
          '<button class="netflix-card-action-btn" data-act="info" title="Detalhes" style="margin-left:auto">' +
            '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M7.41 8.59L12 13.17l4.59-4.58L18 10l-6 6-6-6 1.41-1.41z"/></svg>' +
          '</button>' +
        '</div>' +
        '<div class="netflix-card-detail-meta">' +
          '<span class="netflix-card-match">' + matchScore + '% Match</span>' +
          '<span>' + (c.rating || 'L') + '</span>' +
          '<span>' + (c.quality || 'HD') + '</span>' +
        '</div>' +
        '<div class="netflix-card-detail-desc">' + (c.shortDesc || c.description || '').substring(0, 100) + '</div>' +
      '</div>' +
    '</div>';
  }).join('');

  bindNetflixCardEvents(track);
}

function bindNetflixCardEvents(track) {
  track.querySelectorAll('.netflix-card').forEach(card => {
    const name = card.dataset.name;

    // Click no card geral (não nos botões de detalhe)
    card.querySelector('.netflix-card-inner').addEventListener('click', () => {
      const ch = findChannelByName(name);
      if (ch) playChannel(ch);
    });

    // Ações
    card.querySelectorAll('[data-act]').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const act = btn.dataset.act;
        if (act === 'play') {
          const ch = findChannelByName(name);
          if (ch) playChannel(ch);
        } else if (act === 'fav') {
          toggleFavorite(name);
        } else if (act === 'mylist') {
          toggleMyList(name);
        } else if (act === 'info') {
          openChannelModal(name);
        }
      });
    });
  });
}

// ===== MY LIST (separado de favoritos) =====
function toggleMyList(name) {
  const idx = STATE.myList.indexOf(name);
  if (idx >= 0) {
    STATE.myList.splice(idx, 1);
    showToast('Removido', name + ' fora da minha lista');
  } else {
    STATE.myList.push(name);
    showToast('Adicionado', name + ' adicionado à minha lista');
  }
  saveState();
  renderAllNetflixSections();
}

// ===== CHANNEL MODAL =====
function openChannelModal(name) {
  const ch = findChannelByName(name);
  if (!ch) return;
  STATE.channelDetailsOpen = name;

  const modal = $('channelModal');
  const body = $('channelModalContent');
  if (!modal || !body) return;

  const initials = getInitials(ch.name);
  const matchScore = randomInt(82, 98);
  const isFav = STATE.favorites.includes(name);
  const isMyList = STATE.myList.includes(name);
  const related = (CHANNELS[STATE.currentCountry] || [])
    .filter(c => c.category === ch.category && c.name !== ch.name)
    .slice(0, 6);

  body.innerHTML = '<div class="channel-modal-hero">' +
    '<div class="channel-modal-hero-bg" style="background:linear-gradient(135deg, ' + ch.color + ' 0%, ' + ch.color + 'cc 50%, #0a0a0a 100%)">' + initials + '</div>' +
    '<button class="channel-modal-close" id="channelModalCloseBtn" aria-label="Fechar">' +
      '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/></svg>' +
    '</button>' +
    '<div class="channel-modal-hero-content">' +
      '<span class="channel-modal-eyebrow">AO VIVO &#183; ' + ch.category + '</span>' +
      '<h1 class="channel-modal-title">' + ch.name + '</h1>' +
      '<div class="channel-modal-actions">' +
        '<button class="hero-btn hero-btn-primary" data-act="play">' +
          '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>' +
          'Assistir' +
        '</button>' +
        '<button class="hero-btn hero-btn-secondary" data-act="mylist" title="Minha lista">' +
          '<svg viewBox="0 0 24 24" fill="' + (isMyList ? 'var(--bbc-red)' : 'currentColor') + '"><path d="M' + (isMyList ? '9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z' : '19 13h-6v6h-2v-6H5v-2h6V5h2v6h6v2z') + '"/></svg>' +
        '</button>' +
        '<button class="hero-btn hero-btn-secondary" data-act="fav" title="Favoritar">' +
          '<svg viewBox="0 0 24 24" fill="' + (isFav ? 'var(--bbc-red)' : 'currentColor') + '"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>' +
        '</button>' +
        '<button class="hero-btn hero-btn-secondary" data-act="share" title="Compartilhar">' +
          '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M18 16.08c-.76 0-1.44.3-1.96.77L8.91 12.7c.05-.23.09-.46.09-.7s-.04-.47-.09-.7l7.05-4.11c.54.5 1.25.81 2.04.81 1.66 0 3-1.34 3-3s-1.34-3-3-3-3 1.34-3 3c0 .24.04.47.09.7L8.04 9.81C7.5 9.31 6.79 9 6 9c-1.66 0-3 1.34-3 3s1.34 3 3 3c.79 0 1.5-.31 2.04-.81l7.12 4.16c-.05.21-.08.43-.08.65 0 1.61 1.31 2.92 2.92 2.92 1.61 0 2.92-1.31 2.92-2.92s-1.31-2.92-2.92-2.92z"/></svg>' +
        '</button>' +
      '</div>' +
    '</div>' +
  '</div>' +
  '<div class="channel-modal-body">' +
    '<div class="channel-modal-meta-row">' +
      '<span class="channel-modal-match">' + matchScore + '% Match</span>' +
      '<span class="channel-modal-rating">' + (ch.rating || 'L') + '</span>' +
      '<span style="font-family:var(--font-mono);font-size:11px;color:var(--text-tertiary);letter-spacing:1px;text-transform:uppercase">' + (ch.quality || 'HD') + ' &#183; ' + formatNumber(STATE.channelViewers[ch.name]||0) + ' assistindo</span>' +
      '<div class="channel-modal-tags-list">' +
        (ch.tags || []).map(t => '<span class="channel-modal-tag">' + t + '</span>').join('') +
      '</div>' +
    '</div>' +
    '<p class="channel-modal-description">' + (ch.description || ch.shortDesc || '') + '</p>' +
    '<div class="channel-modal-section">' +
      '<div class="channel-modal-section-title">● Detalhes do canal</div>' +
      '<div class="channel-modal-info-grid">' +
        '<div class="channel-modal-info-cell">' +
          '<span class="channel-modal-info-label">Gênero</span>' +
          '<span class="channel-modal-info-value">' + ch.category + '</span>' +
