        related.map(rel => {
          const relInit = getInitials(rel.name);
          return '<div class="channel-modal-related-card" data-name="' + rel.name + '">' +
            '<div class="channel-modal-related-thumb">' +
              '<div class="channel-modal-related-bg" style="background:linear-gradient(135deg, ' + rel.color + ', ' + rel.color + 'aa)">' + relInit + '</div>' +
            '</div>' +
            '<div class="channel-modal-related-info">' +
              '<div class="channel-modal-related-name">' + rel.name + '</div>' +
              '<div class="channel-modal-related-cat">' + rel.category + '</div>' +
