  // Bind ações
  body.querySelector('#channelModalCloseBtn').addEventListener('click', closeChannelModal);

  body.querySelectorAll('[data-act]').forEach(btn => {
    btn.addEventListener('click', () => {
      const act = btn.dataset.act;
      if (act === 'play') {
        playChannel(ch);
        closeChannelModal();
      } else if (act === 'mylist') {
        toggleMyList(name);
        openChannelModal(name);
      } else if (act === 'fav') {
        toggleFavorite(name);
        openChannelModal(name);
      } else if (act === 'share') {
        openWhatsAppShare(ch);
      }
    });
  });

  body.querySelectorAll('.channel-modal-related-card').forEach(card => {
    card.addEventListener('click', () => {
      openChannelModal(card.dataset.name);
    });
  });

  modal.classList.add('visible');
  document.body.style.overflow = 'hidden';
}

function closeChannelModal() {
  const modal = $('channelModal');
  if (modal) modal.classList.remove('visible');
  STATE.channelDetailsOpen = null;
  document.body.style.overflow = '';
}

// ===== CONTINUE WATCHING =====
function renderContinueWatching() {
  const track = $('continueTrack');
  const section = $('continueSection');
  if (!track || !section) return;

  const items = STATE.history.slice(0, 8)
    .map(name => findChannelByName(name))
    .filter(Boolean);

  if (!items.length) {
    section.style.display = 'none';
    return;
  }

  section.style.display = 'block';

  track.innerHTML = items.map(c => {
    const initials = getInitials(c.name);
    const time = STATE.watchTimes[c.name] || 0;
    const progress = Math.min(85, Math.max(15, (time / 60) * 10 + randomInt(10, 30)));
    const lastSeen = formatLastSeen(STATE.watchTimes[c.name + '_ts'] || Date.now());

    return '<div class="continue-card" data-name="' + c.name + '">' +
      '<div class="continue-thumb">' +
        '<div class="continue-thumb-bg" style="background:linear-gradient(135deg, ' + c.color + ' 0%, ' + c.color + 'cc 60%, #0a0a0a 100%)">' + initials + '</div>' +
        '<div class="continue-card-play"></div>' +
        '<div class="continue-progress">' +
          '<div class="continue-progress-bar" style="width:' + progress + '%"></div>' +
        '</div>' +
      '</div>' +
      '<div class="continue-card-info">' +
        '<div class="continue-card-name">' + c.name + '</div>' +
        '<div class="continue-card-time">' + lastSeen + '</div>' +
      '</div>' +
    '</div>';
  }).join('');

  track.querySelectorAll('.continue-card').forEach(card => {
    card.addEventListener('click', () => {
      const ch = findChannelByName(card.dataset.name);
      if (ch) playChannel(ch);
    });
  });
}

function formatLastSeen(ts) {
  const diff = Date.now() - ts;
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'agora';
  if (mins < 60) return 'há ' + mins + ' min';
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return 'há ' + hrs + 'h';
  const days = Math.floor(hrs / 24);
  return 'há ' + days + ' dia' + (days > 1 ? 's' : '');
}

// ===== ONBOARDING =====
function renderOnboarding() {
  const grid = $('onboardingGenres');
  if (!grid) return;

  grid.innerHTML = GENRE_PREFERENCES.map(g => {
    const active = STATE.selectedGenres.includes(g.id);
    return '<div class="onboarding-genre ' + (active ? 'active' : '') + '" data-id="' + g.id + '">' +
      '<span class="onboarding-genre-icon">' + g.icon + '</span>' +
      '<span class="onboarding-genre-label">' + g.label + '</span>' +
    '</div>';
  }).join('');

  grid.querySelectorAll('.onboarding-genre').forEach(g => {
    g.addEventListener('click', () => {
      const id = g.dataset.id;
      const idx = STATE.selectedGenres.indexOf(id);
      if (idx >= 0) STATE.selectedGenres.splice(idx, 1);
      else STATE.selectedGenres.push(id);
      renderOnboarding();
      updateOnboardingCta();
    });
  });
}

function updateOnboardingCta() {
  const btn = $('onboardingComplete');
  if (!btn) return;
  btn.disabled = STATE.selectedGenres.length === 0;
}

function showOnboarding() {
  STATE.hasOnboarded = true;
  saveState();
  return false;
}

function completeOnboarding(skip) {
  STATE.hasOnboarded = true;
  saveState();
  const modal = $('onboardingModal');
  if (modal) modal.classList.remove('visible');
  if (!skip && STATE.selectedGenres.length > 0) {
    showToast('Preferências salvas', 'Recomendações personalizadas ativas');
  }
  renderAllNetflixSections();
}

function bindOnboarding() {
  const complete = $('onboardingComplete');
  const skip = $('onboardingSkip');
  if (complete) complete.addEventListener('click', () => completeOnboarding(false));
  if (skip) skip.addEventListener('click', () => completeOnboarding(true));
}

// ===== HISTORY watching time tracking =====
function recordWatchStart(channelName) {
  STATE.watchTimes[channelName + '_ts'] = Date.now();
  saveState();
}

// ===== RENDER ALL NETFLIX SECTIONS =====
function renderAllNetflixSections() {
  renderHeroRotator();
  resetHeroTimer();
  renderContinueWatching();
  renderTop10();

  const all = CHANNELS[STATE.currentCountry] || [];

  // Para você (baseado em preferências)
  if (STATE.selectedGenres.length > 0) {
    const preferred = all.filter(c => {
      return STATE.selectedGenres.some(gid => {
        const pref = GENRE_PREFERENCES.find(p => p.id === gid);
        return pref && pref.cat === c.category;
      });
    });
    const rowParaVoce = $('rowParaVoceSection');
    if (rowParaVoce) {
      rowParaVoce.style.display = preferred.length > 0 ? 'block' : 'none';
    }
    renderNetflixRow('rowParaVoce', preferred, preferred.length);
  } else {
    const rowParaVoce = $('rowParaVoceSection');
    if (rowParaVoce) rowParaVoce.style.display = 'none';
  }

  // Notícias
  const noticias = all.filter(c => c.category === 'Notícias');
  renderNetflixRow('rowNoticiasNet', noticias, noticias.length);

  // Esportes
  const esportes = all.filter(c => c.category === 'Esportes');
  renderNetflixRow('rowEsportesNet', esportes, esportes.length);

  // Negócios
  const negocios = all.filter(c => c.category === 'Negócios');
  const rowNegSection = $('rowNegociosSection');
  if (rowNegSection) rowNegSection.style.display = negocios.length > 0 ? 'block' : 'none';
  renderNetflixRow('rowNegociosNet', negocios, negocios.length);

  // Podcast
  const podcasts = all.filter(c => c.category === 'Podcast');
  const rowPodSection = $('rowPodcastSection');
  if (rowPodSection) rowPodSection.style.display = podcasts.length > 0 ? 'block' : 'none';
  renderNetflixRow('rowPodcastNet', podcasts, podcasts.length);

  // Variedades
  const variedades = all.filter(c => c.category === 'Variedades');
  renderNetflixRow('rowVariedadesNet', variedades, variedades.length);

  // Minha lista
  const minhaLista = STATE.myList.map(n => findChannelByName(n)).filter(Boolean);
  const rowMinhaSection = $('rowMinhaListaSection');
  if (rowMinhaSection) rowMinhaSection.style.display = minhaLista.length > 0 ? 'block' : 'none';
  renderNetflixRow('rowMinhaListaNet', minhaLista, minhaLista.length);

  // Porque você assistiu (baseado no último histórico)
  if (STATE.history.length > 0) {
    const lastChannel = findChannelByName(STATE.history[0]);
    if (lastChannel) {
      const similar = all.filter(c =>
        c.category === lastChannel.category && c.name !== lastChannel.name
      );
      const recoSection = $('rowRecoSection');
      const recoTitle = $('rowRecoTitle');
      if (recoSection) recoSection.style.display = similar.length > 0 ? 'block' : 'none';
      if (recoTitle) recoTitle.innerHTML = 'Porque você assistiu <em>' + lastChannel.name + '</em>';
      renderNetflixRow('rowRecoNet', similar, similar.length);
    } else {
      const recoSection = $('rowRecoSection');
      if (recoSection) recoSection.style.display = 'none';
    }
  } else {
    const recoSection = $('rowRecoSection');
    if (recoSection) recoSection.style.display = 'none';
  }
}

