function brtvV13NormalizeText(value) { return String(value || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase(); }
function brtvV13CategoryLabel(id) { const labels = { animation:'Animação', auto:'Automóveis', business:'Negócios', classic:'Clássicos', comedy:'Comédia', cooking:'Culinária', culture:'Cultura', documentary:'Documentários', education:'Educação', entertainment:'Entretenimento', family:'Família', general:'Geral', kids:'Infantil', legislative:'Legislativo', lifestyle:'Lifestyle', movies:'Filmes', music:'Música', outdoor:'Outdoor', relax:'Relax', religious:'Religioso', science:'Ciência', series:'Séries', shop:'Compras', sports:'Esportes', travel:'Viagem', weather:'Tempo', news:'Notícias' }; return labels[id] || 'Geral'; }
function brtvV13CountryFallback(code) { const map = { BR:['Brasil','🇧🇷','America/Sao_Paulo'], US:['Estados Unidos','🇺🇸','America/New_York'], PT:['Portugal','🇵🇹','Europe/Lisbon'], GB:['Reino Unido','🇬🇧','Europe/London'], ES:['Espanha','🇪🇸','Europe/Madrid'], AR:['Argentina','🇦🇷','America/Argentina/Buenos_Aires'], MX:['México','🇲🇽','America/Mexico_City'], FR:['França','🇫🇷','Europe/Paris'], DE:['Alemanha','🇩🇪','Europe/Berlin'], IT:['Itália','🇮🇹','Europe/Rome'], JP:['Japão','🇯🇵','Asia/Tokyo'] }; const data = map[code] || [code, '🌐', 'UTC']; return { name: data[0], flag: data[1], tz: data[2], code: code }; }
function brtvV13EnsureCountry(code, countryMeta) { const up = String(code || '').toUpperCase(); const key = up.toLowerCase(); if (!COUNTRIES[key]) { COUNTRIES[key] = countryMeta || brtvV13CountryFallback(up); } if (!CHANNELS[key]) CHANNELS[key] = []; return key; }
function brtvV13ChannelExists(key, name, iptvId) { const normName = brtvV13NormalizeText(name); const normId = brtvV13NormalizeText(iptvId || ''); return (CHANNELS[key] || []).some(function(ch) { return brtvV13NormalizeText(ch.name) === normName || (normId && brtvV13NormalizeText(ch.iptvId || '') === normId); }); }
function brtvV13MergeStaticChannels() { const key = brtvV13EnsureCountry('BR', { name: 'Brasil', flag: '🇧🇷', tz: 'America/Sao_Paulo', code: 'BR' }); const existing = CHANNELS[key] || []; const clean = existing.filter(function(ch) { return !BRTV_V13_STATIC_CHANNELS.some(function(add) { return brtvV13NormalizeText(add.name) === brtvV13NormalizeText(ch.name) || brtvV13NormalizeText(add.iptvId || '') === brtvV13NormalizeText(ch.iptvId || ''); }); }); CHANNELS[key] = BRTV_V13_STATIC_CHANNELS.concat(clean); }
function brtvV13IsSupportedUrl(url) { const src = String(url || '').trim(); if (!/^https:\/\//i.test(src)) return false; return /(youtube\.com|youtu\.be)/i.test(src) || /(\.m3u8|\.mp4)(\?|#|$)/i.test(src); }
function brtvV13ChooseBestStream(streams) { return (streams || []).filter(function(s) { return s && brtvV13IsSupportedUrl(s.url) && !s.user_agent && !s.referrer; }).sort(function(a, b) { function score(s) { const u = String(s.url || ''); let pts = 0; if (/\.m3u8(\?|#|$)/i.test(u)) pts += 400; if (/(youtube\.com|youtu\.be)/i.test(u)) pts += 380; if (/\.mp4(\?|#|$)/i.test(u)) pts += 160; if (/1080|720|hd/i.test(String(s.quality || '') + ' ' + String(s.label || ''))) pts += 40; return pts; } return score(b) - score(a); })[0] || null; }
function brtvV13SourceType(url) { const src = String(url || ''); if (/(youtube\.com|youtu\.be)/i.test(src)) return 'stream'; if (/\.m3u8(\?|#|$)/i.test(src)) return 'stream'; if (/\.mp4(\?|#|$)/i.test(src)) return 'stream'; return 'stream'; }
async function brtvV13LoadIPTVChannels() { if (window.__BRTV_V13_IPTV_LOADED__) return; window.__BRTV_V13_IPTV_LOADED__ = true; const allowCountries = new Set(BRTV_V13_IMPORT_MATRIX.map(function(item) { return item.country; })); const allowCategories = new Set(BRTV_V13_IMPORT_MATRIX.map(function(item) { return item.category; })); try { const urls = [ 'https://iptv-org.github.io/api/channels.json', 'https://iptv-org.github.io/api/streams.json', 'https://iptv-org.github.io/api/countries.json' ]; const result = await Promise.all(urls.map(function(url) { return fetch(url, { cache: 'no-store' }).then(function(r) { if (!r.ok) throw new Error(url); return r.json(); }); })); const channels = result[0] || []; const streams = result[1] || []; const countries = result[2] || []; const countryByCode = {}; countries.forEach(function(c) { if (!c || !c.code) return; countryByCode[String(c.code).toUpperCase()] = { name: c.name || c.code, flag: c.flag || '🌐', tz: (c.timezones && c.timezones[0]) || 'UTC', code: String(c.code).toUpperCase() }; }); const streamMap = {}; streams.forEach(function(s) { if (!s || !s.channel) return; if (!streamMap[s.channel]) streamMap[s.channel] = []; streamMap[s.channel].push(s); }); let imported = 0; channels.forEach(function(ch) { if (!ch || ch.is_nsfw) return; const country = String(ch.country || '').toUpperCase(); if (!country || !allowCountries.has(country)) return; const cats = String(ch.categories || '').split(/[;,]/).map(function(c) { return c.trim(); }).filter(Boolean); const category = cats.find(function(c) { return allowCategories.has(c); }) || cats[0] || 'general'; if (!allowCategories.has(category)) return; const best = brtvV13ChooseBestStream(streamMap[ch.id]); if (!best) return; const key = brtvV13EnsureCountry(country, countryByCode[country] || brtvV13CountryFallback(country)); if (brtvV13ChannelExists(key, ch.name, ch.id)) return; const isBR = country === 'BR'; const color = isBR ? '#bb1919' : '#1d4ed8'; CHANNELS[key].push({ name: ch.name || ch.id, category: brtvV13CategoryLabel(category), type: brtvV13SourceType(best.url), streamUrl: best.url, color: color, featured: isBR && imported < 18, hero: isBR && imported < 6, rating: 'L', quality: best.quality || best.label || 'Live', tags: ['IPTV', country], description: (ch.name || ch.id) + ' ao vivo via catálogo público integrado ao BR TV NEWS.', shortDesc: brtvV13CategoryLabel(category) + ' · ' + country, open: true, iptvId: ch.id }); imported++; }); if (typeof initViewers === 'function') initViewers(); if (typeof buildCountryDropdown === 'function') buildCountryDropdown(); if (typeof updateCountryUI === 'function') updateCountryUI(); if (typeof renderAll === 'function') renderAll(); if (typeof renderAllNetflixSections === 'function') renderAllNetflixSections(); if (typeof showToast === 'function' && imported > 0) showToast('Canais integrados', imported + ' canais adicionados ao catálogo'); } catch (err) { try { console.warn('BR TV NEWS V13: catálogo IPTV não carregou, mantendo lista local.', err); } catch (_) {} } }
brtvV13MergeStaticChannels(); setTimeout(function() { brtvV13LoadIPTVChannels(); }, 1200);
function init() { // Bootstrap STATE.bootTime = Date.now();
// Carrega estado salvo loadState(); const initialUrlChannel = getInitialChannelFromUrl(); if (!initialUrlChannel && !/[?&](canal|pais|country|categoria|category)=/i.test(window.location.search || '')) { STATE.currentCountry = 'br'; }
// Inicializa viewers initViewers();
// Clock & date updateClock(); updateDate(); setInterval(updateClock, 1000); setInterval(updateDate, 60000);
// Hours on air updateHoursOnAir(); setInterval(updateHoursOnAir, 60000);
// Viewers tick tickViewers(); setInterval(tickViewers, 4000);
// Geolocalização tryGeolocation();
// Rates fetchRates(); setInterval(fetchRates, 60000);
// Volume inicial setVolume(STATE.volume);
// Build & bind UI buildCountryDropdown(); updateCountryUI(); bindCountryButton(); bindMainSearch(); bindChannelListTabs(); bindChannelListSearch(); bindNavigation(); bindPlayerActions(); bindVolumeSlider(); bindKeyboard();
// Render todo o conteúdo renderAll(); renderAllNetflixSections(); updateFavBadge();
// Bind novas features bindHeroControls(); bindOnboarding();
// Bind modal close por backdrop const channelModal = $('channelModal'); if (channelModal) { channelModal.addEventListener('click', (e) => { if (e.target === channelModal) closeChannelModal(); }); }
// Escape fecha o modal document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && STATE.channelDetailsOpen) { closeChannelModal(); } });
// Comments live initFakeComments();
// Editorial time update updateEditorialTime(); setInterval(updateEditorialTime, 90000);
// Footer time setInterval(updateListFooterTime, 30000);
// Re-render Netflix sections quando viewers mudam (a cada 30s) setInterval(() => { if (STATE.currentView === 'home') { renderTop10(); } }, 30000);
// Mobile-only if (STATE.isMobile) { bindPullRefresh(); bindSwipeGestures(); }
// Atualiza isMobile no resize window.addEventListener('resize', () => { STATE.isMobile = window.innerWidth <= 768; });
// Hide splash setTimeout(() => { const splash = $('splashScreen'); if (splash) splash.classList.add('hidden'); }, 1800); // Onboarding removido: o portal abre diretamente no canal inicial.
// Auto-play canal solicitado por link direto ou destaque do país atual setTimeout(() => { const list = CHANNELS[STATE.currentCountry] || []; const featured = initialUrlChannel || list.find(c => c.featured) || list[0]; if (featured) { playChannel(featured, true); if (window.location.hash === '#watch') { const player = document.getElementById('watch') || document.getElementById('playerFrame'); if (player && player.scrollIntoView) player.scrollIntoView({ behavior: 'smooth', block: 'start' }); } } }, 2200);
// Inicializa o sistema PWA (banner de instalação, modal, etc) initPWA(); registerServiceWorker();
// Welcome toast setTimeout(() => { showToast('Bem-vindo', 'BR TV NEWS · Transmissão ao vivo iniciada'); }, 3500); }
if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', init); } else { init(); } /**/
